-- 테이블 mysqlragdb0.ai_reports 구조 내보내기
DROP TABLE IF EXISTS `ai_reports`;
CREATE TABLE IF NOT EXISTS `ai_reports` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint DEFAULT NULL,
  `role` varchar(10) NOT NULL,
  `report_type` varchar(40) NOT NULL,
  `target_type` varchar(20) DEFAULT NULL,
  `target_id` bigint DEFAULT NULL,
  `question` text,
  `answer` longtext NOT NULL,
  `evidence_json` json DEFAULT NULL,
  `provider` varchar(20) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_ai_reports_user` (`user_id`,`created_at`),
  KEY `idx_ai_reports_type` (`report_type`,`created_at`),
  CONSTRAINT `ai_reports_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `app_users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb3;

-- 테이블 데이터 mysqlragdb0.ai_reports:~11 rows (대략적) 내보내기
