INSERT INTO `ai_reports` (`id`, `user_id`, `role`, `report_type`, `target_type`, `target_id`, `question`, `answer`, `evidence_json`, `provider`, `created_at`) VALUES
	(1, 2, 'SELLER', 'COMPLAINT_ASSIST', 'complaint', 106, NULL, '### 상황 요약  \n고객님께서 휴대용 충전기의 충전 케이블 단자가 헐거워 충전이 자주 끊기는 문제를 제기하셨습니다. 이는 제품의 품질 문제로 판단되며, 유사한 사례에서는 제품 회수 검사를 통해 불량 여부를 확인하고 전액 환불 또는 교환 조치를 했습니다.  \n\n### 유사 사례 처리 방식  \n- **불만 105**: 발열 기준 초과 여부 확인을 위해 회수 검사 진행 → 불량 판정 후 전액 환불.  \n- **불만 107**: 펌웨어 업데이트 안내 후 증상 해소. 해소되지 않으면 교환 가능.  \n- **불만 108**: 환불 처리 기간 안내 및 카드 취소 승인번호 전달.  \n\n### 권장 처리 절차 (체크리스트)  \n1. **제품 회수 검사**: 충전 단자 상태 확인 및 불량 여부 판단.  \n2. **불량 판정 시**: 전액 환불 또는 교환 조치 결정.  \n3. **고객 안내**: 검사 결과 및 처리 절차 설명.  \n4. **환불/교환 기간**: 정책에 따라 처리 기간 안내 (정책·매뉴얼 문서 미 제공으로 인해 \'담당자 확인 필요\').  \n\n### 고객 응대 초안  \n고객님,  \n고객님의 휴대용 충전기 사용 중 충전 케이블 단자가 헐거워 충전이 자주 끊기는 문제가 발생하셨다는 내용을 확인하였습니다. 이에 대해 제품의 품질 문제로 판단되며, 다음과 같은 조치를 안내드립니다.  \n\n1. **제품 회수 검사**: 충전 단자 상태를 확인하여 불량 여부를 판단할 예정입니다.  \n2. **불량 판정 시**: 전액 환불 또는 교환 조치가 가능하며, 처리 절차를 안내드리겠습니다.  \n3. **환불/교환 기간**: 정책에 따라 처리 기간이 다르므로, 담당자와의 확인 후 안내드리겠습니다.  \n\n고객님의 불편을 최소화하기 위해 신속한 조치를 위해 노력하겠습니다. 추가 문의 사항이 있으시면 언제든지 문의 주시기 바랍니다.  \n\n감사합니다.', '{"sources": [{"id": 105, "kind": "complaint", "score": 0.835, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 품질 / 상태: RESOLVED / 상품: 휴대용 충전기 / 내용: 충전기가 사용 중 뜨거워지고 완충까지 너무 오래 걸립니다. 안전한지 확인 부탁드립니다. / 처리결과: 발열 기준 초과 여부 확인을 위해 회수 검사 진행. 불량 판정되어 전액 환불 처리. 동일 로트 제품 품질 점검 요청.", "category": "품질", "order_id": 107, "seller_id": 1, "product_id": 6, "has_resolution": true, "source_created_at": "2026-09-18 16:49:04"}, {"id": 107, "kind": "complaint", "score": 0.824, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 품질 / 상태: RESOLVED / 상품: 블루투스 스피커 / 내용: 블루투스 스피커 연결이 자주 끊깁니다. / 처리결과: 펌웨어 최신 버전 업데이트 방법 안내 후 증상 해소. 해소되지 않으면 교환 가능함을 안내.", "category": "품질", "order_id": 106, "seller_id": 1, "product_id": 2, "has_resolution": true, "source_created_at": "2026-09-13 16:49:04"}, {"id": 108, "kind": "complaint", "score": 0.808, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 환불 / 상태: RESOLVED / 상품: 무선 이어폰 / 내용: 이어폰 한쪽 소리가 작아서 환불 요청했는데 환불 금액이 아직 입금되지 않았습니다. / 처리결과: 카드사 환불 처리 기간 3~5영업일 안내 및 카드 취소 승인번호 전달. 이후 입금 확인.", "category": "환불", "order_id": 115, "seller_id": 1, "product_id": 1, "has_resolution": true, "source_created_at": "2026-08-05 16:49:04"}, {"id": 115, "kind": "review", "score": 0.851, "rating": 2, "excerpt": "[상품후기] 상품: 휴대용 충전기(전자기기) / 평점: 2점 / 내용: 케이블 단자가 헐거워 충전이 자주 끊깁니다. 충전 속도도 광고보다 느립니다.", "category": "전자기기", "seller_id": 1, "product_id": 6, "source_created_at": "2026-09-15 16:49:04"}, {"id": 2, "kind": "review", "score": 0.843, "rating": 2, "excerpt": "[상품후기] 상품: 휴대용 충전기(전자기기) / 평점: 2점 / 내용: 충전 속도가 느려서 이 충전기는 다시 구매하고 싶지 않습니다.", "category": "전자기기", "seller_id": 1, "product_id": 6, "source_created_at": "2026-09-24 13:26:15"}, {"id": 107, "kind": "review", "score": 0.822, "rating": 1, "excerpt": "[상품후기] 상품: 휴대용 충전기(전자기기) / 평점: 1점 / 내용: 완충까지 5시간 이상 걸리고 사용 중 뜨거워집니다. 발열이 걱정됩니다.", "category": "전자기기", "seller_id": 1, "product_id": 6, "source_created_at": "2026-09-17 16:49:04"}]}', 'local', '2026-09-29 16:50:32'),
	(2, 6, 'BUYER', 'RAG_ASK', NULL, NULL, '휴대용 충전기 발열 문제 있나요? 사도 될까요?', '[후기 107] 일부 구매자는 휴대용 충전기 사용 중 발열 문제가 발생했다고 보고했습니다. 완충까지 5시간 이상 걸리고, 사용 중 뜨거워지는 문제가 있어 걱정된다고 합니다. 휴대용 충전기 구매 여부는 상품 페이지에서 확인하시고, 환불·교환 확정 여부는 고객센터에 문의하시기 바랍니다.', '{"sources": [{"id": 115, "kind": "review", "score": 0.865, "rating": 2, "excerpt": "[상품후기] 상품: 휴대용 충전기(전자기기) / 평점: 2점 / 내용: 케이블 단자가 헐거워 충전이 자주 끊깁니다. 충전 속도도 광고보다 느립니다.", "category": "전자기기", "seller_id": 1, "product_id": 6, "source_created_at": "2026-09-15 16:49:04"}, {"id": 2, "kind": "review", "score": 0.848, "rating": 2, "excerpt": "[상품후기] 상품: 휴대용 충전기(전자기기) / 평점: 2점 / 내용: 충전 속도가 느려서 이 충전기는 다시 구매하고 싶지 않습니다.", "category": "전자기기", "seller_id": 1, "product_id": 6, "source_created_at": "2026-09-24 13:26:15"}, {"id": 112, "kind": "review", "score": 0.834, "rating": 4, "excerpt": "[상품후기] 상품: 요가 매트(운동용품) / 평점: 4점 / 내용: 미끄럼 방지는 좋은데 처음에 고무 냄새가 강했습니다. 며칠 환기하니 괜찮아요.", "category": "운동용품", "seller_id": 3, "product_id": 5, "source_created_at": "2026-09-03 16:49:04"}, {"id": 107, "kind": "review", "score": 0.821, "rating": 1, "excerpt": "[상품후기] 상품: 휴대용 충전기(전자기기) / 평점: 1점 / 내용: 완충까지 5시간 이상 걸리고 사용 중 뜨거워집니다. 발열이 걱정됩니다.", "category": "전자기기", "seller_id": 1, "product_id": 6, "source_created_at": "2026-09-17 16:49:04"}, {"id": 114, "kind": "review", "score": 0.818, "rating": 4, "excerpt": "[상품후기] 상품: 스마트 워치(전자기기) / 평점: 4점 / 내용: 심박 측정이 정확하고 디자인이 좋습니다. 배터리는 이틀 정도 갑니다.", "category": "전자기기", "seller_id": 1, "product_id": 8, "source_created_at": "2026-09-27 16:49:04"}, {"id": 111, "kind": "review", "score": 0.803, "rating": 2, "excerpt": "[상품후기] 상품: 밀폐 유리 용기 세트(생활용품) / 평점: 2점 / 내용: 배송 중 유리 용기 하나가 깨져서 왔습니다. 포장 완충재가 부족했습니다.", "category": "생활용품", "seller_id": 2, "product_id": 9, "source_created_at": "2026-09-25 16:49:04"}, {"id": 106, "kind": "complaint", "score": 0.769, "status": "IN_PROGRESS", "excerpt": "[고객불만] 분류: 품질 / 상태: IN_PROGRESS / 상품: 휴대용 충전기 / 내용: 충전 케이블 단자가 헐거워 충전이 자주 끊깁니다.", "category": "품질", "order_id": 112, "seller_id": 1, "product_id": 6, "has_resolution": false, "source_created_at": "2026-09-16 16:49:04"}, {"id": 3, "kind": "complaint", "score": 0.731, "status": "IN_PROGRESS", "excerpt": "[고객불만] 분류: 교환 / 상태: IN_PROGRESS / 상품: 보온 텀블러 / 내용: 텀블러 뚜껑에 흠집이 있어 교환하고 싶습니다.", "category": "교환", "order_id": 3, "seller_id": 2, "product_id": 3, "has_resolution": false, "source_created_at": "2026-09-29 13:26:15"}]}', 'local', '2026-09-29 16:50:45'),
	(3, 2, 'SELLER', 'REVIEW_SUMMARY', 'product', 6, NULL, '1) 한 줄 요약  \n충전 속도 저하, 케이블 단자 불안정, 과열 문제로 인한 부정적 평가가 집중된 휴대용 충전기입니다.  \n\n2) 장점  \n고가의 휴대용 충전기로, 품질과 성능을 보장한다고 설명할 수 있습니다.  \n\n3) 단점·주의점  \n- 케이블 단자 헐거움 (후기 115, 불만 106)  \n- 충전 속도 느림 (후기 2, 115, 불만 2)  \n- 과열 및 안전성 우려 (후기 107, 불만 105)  \n\n4) 판매자 개선 액션  \n- **상품 상세페이지**: 충전 속도와 케이블 단자 안정성에 대한 명확한 사양 기재, 사용 시 주의 사항 명시.  \n- **품질**: 과열 방지 기능 강화, 단자 고정 구조 개선, 제조 공정 검수 강화.  \n- **포장**: 제품 안정성 확인을 위한 추가 포장 재고 확보.  \n- **CS**: 불만 처리 시 신속한 검사 및 전액 환불 절차 마련, 사용자 피드백 반영한 개선 사항 공유.  \n\n5) 불만과 후기의 공통 원인  \n제품의 성능(충전 속도)과 설계(단자 고정, 발열 방지)가 기대에 미치지 못해 발생한 품질 문제로, 사용자 안전과 사용 경험에 직간접적으로 영향을 미쳤습니다.', '{"stats": {"neutral": "0", "reviews": 3, "negative": "3", "positive": "0", "avg_rating": "1.67"}, "sources": [{"id": 115, "kind": "review", "score": 0.846, "rating": 2, "excerpt": "[상품후기] 상품: 휴대용 충전기(전자기기) / 평점: 2점 / 내용: 케이블 단자가 헐거워 충전이 자주 끊깁니다. 충전 속도도 광고보다 느립니다.", "category": "전자기기", "seller_id": 1, "product_id": 6, "source_created_at": "2026-09-15 16:49:04"}, {"id": 2, "kind": "review", "score": 0.83, "rating": 2, "excerpt": "[상품후기] 상품: 휴대용 충전기(전자기기) / 평점: 2점 / 내용: 충전 속도가 느려서 이 충전기는 다시 구매하고 싶지 않습니다.", "category": "전자기기", "seller_id": 1, "product_id": 6, "source_created_at": "2026-09-24 13:26:15"}, {"id": 107, "kind": "review", "score": 0.797, "rating": 1, "excerpt": "[상품후기] 상품: 휴대용 충전기(전자기기) / 평점: 1점 / 내용: 완충까지 5시간 이상 걸리고 사용 중 뜨거워집니다. 발열이 걱정됩니다.", "category": "전자기기", "seller_id": 1, "product_id": 6, "source_created_at": "2026-09-17 16:49:04"}, {"id": 105, "kind": "complaint", "score": 0.811, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 품질 / 상태: RESOLVED / 상품: 휴대용 충전기 / 내용: 충전기가 사용 중 뜨거워지고 완충까지 너무 오래 걸립니다. 안전한지 확인 부탁드립니다. / 처리결과: 발열 기준 초과 여부 확인을 위해 회수 검사 진행. 불량 판정되어 전액 환불 처리. 동일 로트 제품 품질 점검 요청.", "category": "품질", "order_id": 107, "seller_id": 1, "product_id": 6, "has_resolution": true, "source_created_at": "2026-09-18 16:49:04"}, {"id": 2, "kind": "complaint", "score": 0.807, "status": "OPEN", "excerpt": "[고객불만] 분류: 품질 / 상태: OPEN / 상품: 휴대용 충전기 / 내용: 휴대용 충전기 충전 속도가 안내보다 느립니다.", "category": "품질", "order_id": 2, "seller_id": 1, "product_id": 6, "has_resolution": false, "source_created_at": "2026-09-29 13:26:15"}, {"id": 106, "kind": "complaint", "score": 0.799, "status": "IN_PROGRESS", "excerpt": "[고객불만] 분류: 품질 / 상태: IN_PROGRESS / 상품: 휴대용 충전기 / 내용: 충전 케이블 단자가 헐거워 충전이 자주 끊깁니다.", "category": "품질", "order_id": 112, "seller_id": 1, "product_id": 6, "has_resolution": false, "source_created_at": "2026-09-16 16:49:04"}]}', 'local', '2026-09-29 16:55:26'),
	(4, 1, 'ADMIN', 'INSIGHT', NULL, NULL, '최근 90일', '### 운영 리포트  \n\n---\n\n#### **1) 핵심 이슈 Top 3**  \n**1. 품질 문제 (영향 범위: 5건, 근거: 불만 105, 불만 2, 불만 107, 불만 111, 후기 115)**  \n- 휴대용 충전기의 충전 속도 저하, 발열, 케이블 단자 불량 등으로 반복된 불만 발생.  \n- **불만 105**: 전액 환불 및 동일 로트 품질 점검 요청.  \n- **불만 2**: 충전 속도 느림으로 인한 불만 접수.  \n- **불만 107**: 블루투스 스피커 연결 중단 문제.  \n\n**2. 배송/포장 문제 (영향 범위: 4건, 근거: 불만 104, 불만 111, 후기 111, 후기 113)**  \n- 밀폐 유리 용기 세트, 폼롤러 등 상품의 포장 부족으로 인한 파손 및 배송 중 손상.  \n- **불만 104**: 유리 용기 파손으로 재발송 처리.  \n- **후기 111**: 배송 중 유리 용기 파손.  \n- **불만 111**: 데스크 조명 박스 찌그러짐.  \n\n**3. 상품 성능 문제 (영향 범위: 3건, 근거: 후기 106, 후기 113, 후기 2)**  \n- 블루투스 스피커 저음 약함, 폼롤러 표면 딱딱함, 휴대용 충전기 충전 속도 느림으로 인한 부정 후기.  \n- **후기 106**: 저음 약하고 연결 중단.  \n- **후기 113**: 폼롤러 표면 딱딱, 통증 유발.  \n- **후기 2**: 충전 속도 느림으로 인한 구매 포기.  \n\n---\n\n#### **2) 상품별 위험 신호**  \n- **휴대용 충전기**:  \n  - 품질 불만 3건 (불만 105, 불만 2, 후기 115).  \n  - 충전 속도, 발열, 케이블 단자 불량 반복.  \n- **밀폐 유리 용기 세트**:  \n  - 배송 중 파손 2건 (불만 104, 후기 111).  \n  - 포장 완충재 부족으로 인한 손상.  \n- **블루투스 스피커**:  \n  - 연결 중단 및 저음 문제 2건 (불만 107, 후기 106).  \n- **폼롤러**:  \n  - 표면 딱딱함으로 인한 부정 후기 (후기 113).  \n\n---\n\n#### **3) 이번 주 즉시 조치**  \n1. **품질 문제 대응**:  \n   - 휴대용 충전기 생산라인 점검 및 재검사 (불만 105, 불만 2).  \n   - 불량 로트 제품 전량 회수 및 교체 (불만 105).  \n2. **배송/포장 개선**:  \n   - 밀폐 유리 용기 세트 포장 완충재 2중 적용 (불만 104, 후기 111).  \n   - 택배사와 협의하여 파손 접수 절차 명확화.  \n3. **상품 성능 개선**:  \n   - 블루투스 스피커 펌웨어 업데이트 안내 및 교환 대응 준비 (불만 107).  \n   - 폼롤러 표면 소프트 처리 또는 디자인 변경 검토 (후기 113).  \n\n---\n\n#### **4) 정책·매뉴얼·상세페이지 개선 제안**  \n- **정책 개선**:  \n  - 품질 불만 처리 기준 명확화: 동일 로트 제품 품질 점검 필수.  \n  - 배송 파손 시 2중 포장 적용 의무화.  \n- **매뉴얼 개선**:  \n  - 상품별 충전 속도, 소음 수준 등 기술 사양 표기 의무화.  \n  - 포장 부족으로 인한 배송 손상 시 즉시 교환/재발송 절차 명시.  \n- **상세페이지 개선**:  \n  - 휴대용 충전기: 충전 속도, 발열 기준 등 기술적 정보 추가.  \n  - 블루투스 스피커: 저음 수준, 연결 안정성 관련 정보 표기.  \n  - 밀폐 유리 용기 세트: 포장 방식 및 파손 방지 방법 설명.  \n\n---\n\n#### **5) 추적할 지표**  \n1. **불만 처리 완료율**: 품질/배송 불만 RESOLVED 비율 (현재 5/7).  \n2. **반복 불만 발생률**: 동일 상품/분류 불만 재발 여부.  \n3. **상품 평점 변화**: 휴대용 충전기, 블루투스 스피커 등 낮은 평점 상품의 개선 효과.  \n4. **배송 파손률**: 밀폐 유리 용기 세트, 폼롤러 등 포장 관련 손상 발생률.  \n5. **환불/교환 비율**: 품질/배송 문제로 인한 환불/교환 건수 추이.', '{"stats": {"reviews": [{"id": 6, "name": "휴대용 충전기", "reviews": 3, "negative": "3", "avg_rating": "1.67"}, {"id": 9, "name": "밀폐 유리 용기 세트", "reviews": 1, "negative": "1", "avg_rating": "2.00"}, {"id": 2, "name": "블루투스 스피커", "reviews": 1, "negative": "0", "avg_rating": "3.00"}, {"id": 10, "name": "폼롤러", "reviews": 2, "negative": "0", "avg_rating": "4.00"}, {"id": 5, "name": "요가 매트", "reviews": 1, "negative": "0", "avg_rating": "4.00"}, {"id": 8, "name": "스마트 워치", "reviews": 1, "negative": "0", "avg_rating": "4.00"}, {"id": 1, "name": "무선 이어폰", "reviews": 2, "negative": "0", "avg_rating": "4.50"}, {"id": 3, "name": "보온 텀블러", "reviews": 2, "negative": "0", "avg_rating": "4.50"}, {"id": 4, "name": "데스크 조명", "reviews": 2, "negative": "0", "avg_rating": "5.00"}, {"id": 7, "name": "노이즈캔슬링 헤드폰", "reviews": 1, "negative": "0", "avg_rating": "5.00"}], "complaints": [{"n": 4, "status": "RESOLVED", "category": "품질"}, {"n": 3, "status": "OPEN", "category": "배송"}, {"n": 1, "status": "OPEN", "category": "품질"}, {"n": 1, "status": "IN_PROGRESS", "category": "교환"}, {"n": 1, "status": "RESOLVED", "category": "배송파손"}, {"n": 1, "status": "IN_PROGRESS", "category": "품질"}, {"n": 1, "status": "RESOLVED", "category": "환불"}, {"n": 1, "status": "RESOLVED", "category": "배송"}, {"n": 1, "status": "OPEN", "category": "교환"}, {"n": 1, "status": "RESOLVED", "category": "문의"}]}, "sources": [{"id": 113, "kind": "review", "score": 0.821, "rating": 3, "excerpt": "[상품후기] 상품: 폼롤러(운동용품) / 평점: 3점 / 내용: 표면이 딱딱해서 초보자에게는 통증이 있습니다. 부드러운 버전이 있으면 좋겠어요.", "category": "운동용품", "seller_id": 3, "product_id": 10, "customer_id": 5, "source_created_at": "2026-09-03 16:49:04"}, {"id": 106, "kind": "review", "score": 0.809, "rating": 3, "excerpt": "[상품후기] 상품: 블루투스 스피커(전자기기) / 평점: 3점 / 내용: 음량은 충분하지만 저음이 약하고 블루투스 연결이 가끔 끊깁니다.", "category": "전자기기", "seller_id": 1, "product_id": 2, "customer_id": 3, "source_created_at": "2026-09-12 16:49:04"}, {"id": 115, "kind": "review", "score": 0.802, "rating": 2, "excerpt": "[상품후기] 상품: 휴대용 충전기(전자기기) / 평점: 2점 / 내용: 케이블 단자가 헐거워 충전이 자주 끊깁니다. 충전 속도도 광고보다 느립니다.", "category": "전자기기", "seller_id": 1, "product_id": 6, "customer_id": 2, "source_created_at": "2026-09-15 16:49:04"}, {"id": 105, "kind": "complaint", "score": 0.816, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 품질 / 상태: RESOLVED / 상품: 휴대용 충전기 / 내용: 충전기가 사용 중 뜨거워지고 완충까지 너무 오래 걸립니다. 안전한지 확인 부탁드립니다. / 처리결과: 발열 기준 초과 여부 확인을 위해 회수 검사 진행. 불량 판정되어 전액 환불 처리. 동일 로트 제품 품질 점검 요청.", "category": "품질", "order_id": 107, "seller_id": 1, "product_id": 6, "customer_id": 3, "has_resolution": true, "source_created_at": "2026-09-18 16:49:04"}, {"id": 2, "kind": "complaint", "score": 0.815, "status": "OPEN", "excerpt": "[고객불만] 분류: 품질 / 상태: OPEN / 상품: 휴대용 충전기 / 내용: 휴대용 충전기 충전 속도가 안내보다 느립니다.", "category": "품질", "order_id": 2, "seller_id": 1, "product_id": 6, "customer_id": 1, "has_resolution": false, "source_created_at": "2026-09-29 13:26:15"}, {"id": 114, "kind": "complaint", "score": 0.81, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 품질 / 상태: RESOLVED / 상품: 보온 텀블러 / 내용: 텀블러 뚜껑이 잘 닫히지 않아 음료가 샙니다. / 처리결과: 뚜껑 패킹 불량 확인 후 교체용 패킹 무상 발송.", "category": "품질", "order_id": 109, "seller_id": 2, "product_id": 3, "customer_id": 4, "has_resolution": true, "source_created_at": "2026-09-29 16:54:48"}, {"id": 111, "kind": "review", "score": 0.82, "rating": 2, "excerpt": "[상품후기] 상품: 밀폐 유리 용기 세트(생활용품) / 평점: 2점 / 내용: 배송 중 유리 용기 하나가 깨져서 왔습니다. 포장 완충재가 부족했습니다.", "category": "생활용품", "seller_id": 2, "product_id": 9, "customer_id": 4, "source_created_at": "2026-09-25 16:49:04"}, {"id": 107, "kind": "complaint", "score": 0.808, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 품질 / 상태: RESOLVED / 상품: 블루투스 스피커 / 내용: 블루투스 스피커 연결이 자주 끊깁니다. / 처리결과: 펌웨어 최신 버전 업데이트 방법 안내 후 증상 해소. 해소되지 않으면 교환 가능함을 안내.", "category": "품질", "order_id": 106, "seller_id": 1, "product_id": 2, "customer_id": 3, "has_resolution": true, "source_created_at": "2026-09-13 16:49:04"}, {"id": 104, "kind": "complaint", "score": 0.802, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 배송파손 / 상태: RESOLVED / 상품: 밀폐 유리 용기 세트 / 내용: 유리 용기 세트 중 1개가 깨진 상태로 도착했습니다. 사진 첨부 가능합니다. / 처리결과: 파손 사진 확인 후 동일 상품 1개 무상 재발송. 택배사 파손 접수 및 포장 완충재 2중 적용 기준으로 변경.", "category": "배송파손", "order_id": 109, "seller_id": 2, "product_id": 9, "customer_id": 4, "has_resolution": true, "source_created_at": "2026-09-25 16:49:04"}, {"id": 2, "kind": "review", "score": 0.776, "rating": 2, "excerpt": "[상품후기] 상품: 휴대용 충전기(전자기기) / 평점: 2점 / 내용: 충전 속도가 느려서 이 충전기는 다시 구매하고 싶지 않습니다.", "category": "전자기기", "seller_id": 1, "product_id": 6, "customer_id": 1, "source_created_at": "2026-09-24 13:26:15"}, {"id": 108, "kind": "complaint", "score": 0.805, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 환불 / 상태: RESOLVED / 상품: 무선 이어폰 / 내용: 이어폰 한쪽 소리가 작아서 환불 요청했는데 환불 금액이 아직 입금되지 않았습니다. / 처리결과: 카드사 환불 처리 기간 3~5영업일 안내 및 카드 취소 승인번호 전달. 이후 입금 확인.", "category": "환불", "order_id": 115, "seller_id": 1, "product_id": 1, "customer_id": 5, "has_resolution": true, "source_created_at": "2026-08-05 16:49:04"}, {"id": 111, "kind": "complaint", "score": 0.791, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 배송 / 상태: RESOLVED / 상품: 데스크 조명 / 내용: 데스크 조명 박스가 찌그러져 도착했습니다. 제품은 정상 작동합니다. / 처리결과: 제품 정상 작동 확인. 사과와 함께 적립금 2,000원 지급. 판매자에게 포장 개선 요청 전달.", "category": "배송", "order_id": 113, "seller_id": 2, "product_id": 4, "customer_id": 1, "has_resolution": true, "source_created_at": "2026-08-12 16:49:04"}]}', 'local', '2026-09-29 16:56:17'),
	(5, 2, 'SELLER', 'REVIEW_SUMMARY', 'product', 6, NULL, '1) 한 줄 요약  \n[후기 115][후기 2][후기 107][불만 2][불만 105][불만 106] 휴대용 충전기의 케이블 단자 불량, 충전 속도 저하, 과열 문제로 인해 낮은 평점과 불만 발생.  \n\n2) 장점  \n근거 없음  \n\n3) 단점·주의점  \n- 케이블 단자 헐거움 (후기 115, 불만 106)  \n- 충전 속도 느림 (후기 115, 후기 2, 불만 2)  \n- 과열 현상 (후기 107, 불만 105)  \n\n4) 판매자 개선 액션  \n- **상품 상세페이지**: 충전 속도, 발열 방지 기능, 케이블 단자 구조에 대한 명확한 설명 추가.  \n- **품질**: 케이블 단자 고정력 강화, 과열 방지 회로 설계 개선. 동일 로트 제품 품질 점검 요청 (불만 105).  \n- **포장**: 열 절연 재질 사용으로 사용 중 발열 방지.  \n- **CS**: 불량 제품 회수 정책 명시, 반품/환불 절차 간소화.  \n\n5) 불만과 후기의 공통 원인  \n[불만 105][불만 2][불만 106] 제품의 품질 문제 (케이블 단자 불량, 충전 속도 저하, 과열)로 인한 사용자 불만 및 후기 부정 평가. 제조사의 품질 관리 미흡이 주요 원인.', '{"stats": {"neutral": "0", "reviews": 3, "negative": "3", "positive": "0", "avg_rating": "1.67"}, "sources": [{"id": 115, "kind": "review", "score": 0.846, "rating": 2, "excerpt": "[상품후기] 상품: 휴대용 충전기(전자기기) / 평점: 2점 / 내용: 케이블 단자가 헐거워 충전이 자주 끊깁니다. 충전 속도도 광고보다 느립니다.", "category": "전자기기", "seller_id": 1, "product_id": 6, "source_created_at": "2026-09-15 16:49:04"}, {"id": 2, "kind": "review", "score": 0.83, "rating": 2, "excerpt": "[상품후기] 상품: 휴대용 충전기(전자기기) / 평점: 2점 / 내용: 충전 속도가 느려서 이 충전기는 다시 구매하고 싶지 않습니다.", "category": "전자기기", "seller_id": 1, "product_id": 6, "source_created_at": "2026-09-24 13:26:15"}, {"id": 107, "kind": "review", "score": 0.797, "rating": 1, "excerpt": "[상품후기] 상품: 휴대용 충전기(전자기기) / 평점: 1점 / 내용: 완충까지 5시간 이상 걸리고 사용 중 뜨거워집니다. 발열이 걱정됩니다.", "category": "전자기기", "seller_id": 1, "product_id": 6, "source_created_at": "2026-09-17 16:49:04"}, {"id": 105, "kind": "complaint", "score": 0.811, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 품질 / 상태: RESOLVED / 상품: 휴대용 충전기 / 내용: 충전기가 사용 중 뜨거워지고 완충까지 너무 오래 걸립니다. 안전한지 확인 부탁드립니다. / 처리결과: 발열 기준 초과 여부 확인을 위해 회수 검사 진행. 불량 판정되어 전액 환불 처리. 동일 로트 제품 품질 점검 요청.", "category": "품질", "order_id": 107, "seller_id": 1, "product_id": 6, "has_resolution": true, "source_created_at": "2026-09-18 16:49:04"}, {"id": 2, "kind": "complaint", "score": 0.807, "status": "OPEN", "excerpt": "[고객불만] 분류: 품질 / 상태: OPEN / 상품: 휴대용 충전기 / 내용: 휴대용 충전기 충전 속도가 안내보다 느립니다.", "category": "품질", "order_id": 2, "seller_id": 1, "product_id": 6, "has_resolution": false, "source_created_at": "2026-09-29 13:26:15"}, {"id": 106, "kind": "complaint", "score": 0.799, "status": "IN_PROGRESS", "excerpt": "[고객불만] 분류: 품질 / 상태: IN_PROGRESS / 상품: 휴대용 충전기 / 내용: 충전 케이블 단자가 헐거워 충전이 자주 끊깁니다.", "category": "품질", "order_id": 112, "seller_id": 1, "product_id": 6, "has_resolution": false, "source_created_at": "2026-09-16 16:49:04"}]}', 'local', '2026-09-29 16:59:36'),
	(6, 1, 'ADMIN', 'RAG_ASK', NULL, NULL, '배송 미수령 불만에는 어떻게 응답해야 하나요?', '배송 미수령 불만 처리 기준 및 운영 개선안은 다음과 같습니다:  \n\n### **처리 기준**  \n1. **배송 상태 확인**: [불만 1]에 따르면, 배송 완료로 표시되었으나 상품을 수령하지 못한 경우, 택배사와 협의하여 배송 추적 정보를 확인하고, 실제 배송 상태를 파악해야 합니다.  \n2. **상황별 대응**:  \n   - **배송 중 실수**: 택배사와 협력해 상품 위치 확인 후, 고객에게 연락하여 수령 절차를 안내합니다.  \n   - **배송 실패**: 재배송을 제안하거나, 고객의 편의를 위해 교환/환불 절차를 신속히 진행합니다.  \n   - **의도적 미수령**: 고객의 사전 통보가 없는 경우, 배송 완료로 자동 처리될 수 있으나, [불만 1]처럼 상황이 불분명할 경우 추가 조치가 필요합니다.  \n\n### **운영 개선안**  \n1. **포장 강화**: [불만 104]에서 유리 용기 파손 사례를 반영해, 고가 상품은 2중 완충재 적용을 의무화하고, 포장 상태 검사를 강화해야 합니다.  \n2. **배송 추적 시스템 개선**: 고객이 배송 상태를 실시간으로 확인할 수 있도록 추적 코드 제공 및 알림 기능을 확대해야 합니다.  \n3. **고객 피드백 반영**: [후기 111]과 같은 포장 부족 사례를 분석해, 상품별 포장 강도 기준을 재검토하고, 품질 저하 위험 상품에 대한 예방적 조치를 도입해야 합니다.  \n\n**참고 근거**: [불만 1], [불만 104]', '{"sources": [{"id": 112, "kind": "review", "score": 0.801, "rating": 4, "excerpt": "[상품후기] 상품: 요가 매트(운동용품) / 평점: 4점 / 내용: 미끄럼 방지는 좋은데 처음에 고무 냄새가 강했습니다. 며칠 환기하니 괜찮아요.", "category": "운동용품", "seller_id": 3, "product_id": 5, "customer_id": 5, "source_created_at": "2026-09-03 16:49:04"}, {"id": 111, "kind": "review", "score": 0.798, "rating": 2, "excerpt": "[상품후기] 상품: 밀폐 유리 용기 세트(생활용품) / 평점: 2점 / 내용: 배송 중 유리 용기 하나가 깨져서 왔습니다. 포장 완충재가 부족했습니다.", "category": "생활용품", "seller_id": 2, "product_id": 9, "customer_id": 4, "source_created_at": "2026-09-25 16:49:04"}, {"id": 113, "kind": "review", "score": 0.787, "rating": 3, "excerpt": "[상품후기] 상품: 폼롤러(운동용품) / 평점: 3점 / 내용: 표면이 딱딱해서 초보자에게는 통증이 있습니다. 부드러운 버전이 있으면 좋겠어요.", "category": "운동용품", "seller_id": 3, "product_id": 10, "customer_id": 5, "source_created_at": "2026-09-03 16:49:04"}, {"id": 104, "kind": "review", "score": 0.783, "rating": 4, "excerpt": "[상품후기] 상품: 무선 이어폰(전자기기) / 평점: 4점 / 내용: 통화 품질이 깔끔하고 가볍습니다. 다만 충전 케이스 힌지가 약간 헐거워요.", "category": "전자기기", "seller_id": 1, "product_id": 1, "customer_id": 2, "source_created_at": "2026-08-25 16:49:04"}, {"id": 106, "kind": "review", "score": 0.783, "rating": 3, "excerpt": "[상품후기] 상품: 블루투스 스피커(전자기기) / 평점: 3점 / 내용: 음량은 충분하지만 저음이 약하고 블루투스 연결이 가끔 끊깁니다.", "category": "전자기기", "seller_id": 1, "product_id": 2, "customer_id": 3, "source_created_at": "2026-09-12 16:49:04"}, {"id": 110, "kind": "review", "score": 0.779, "rating": 4, "excerpt": "[상품후기] 상품: 보온 텀블러(생활용품) / 평점: 4점 / 내용: 보온은 6시간 정도 유지됩니다. 뚜껑 패킹 세척이 조금 번거롭습니다.", "category": "생활용품", "seller_id": 2, "product_id": 3, "customer_id": 4, "source_created_at": "2026-09-25 16:49:04"}, {"id": 1, "kind": "complaint", "score": 0.772, "status": "OPEN", "excerpt": "[고객불만] 분류: 배송 / 상태: OPEN / 상품: 무선 이어폰 / 내용: 배송 완료로 표시되었으나 상품을 받지 못했습니다.", "category": "배송", "order_id": 1, "seller_id": 1, "product_id": 1, "customer_id": 1, "has_resolution": false, "source_created_at": "2026-09-29 13:26:15"}, {"id": 104, "kind": "complaint", "score": 0.771, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 배송파손 / 상태: RESOLVED / 상품: 밀폐 유리 용기 세트 / 내용: 유리 용기 세트 중 1개가 깨진 상태로 도착했습니다. 사진 첨부 가능합니다. / 처리결과: 파손 사진 확인 후 동일 상품 1개 무상 재발송. 택배사 파손 접수 및 포장 완충재 2중 적용 기준으로 변경.", "category": "배송파손", "order_id": 109, "seller_id": 2, "product_id": 9, "customer_id": 4, "has_resolution": true, "source_created_at": "2026-09-25 16:49:04"}, {"id": 2, "kind": "complaint", "score": 0.768, "status": "OPEN", "excerpt": "[고객불만] 분류: 품질 / 상태: OPEN / 상품: 휴대용 충전기 / 내용: 휴대용 충전기 충전 속도가 안내보다 느립니다.", "category": "품질", "order_id": 2, "seller_id": 1, "product_id": 6, "customer_id": 1, "has_resolution": false, "source_created_at": "2026-09-29 13:26:15"}, {"id": 105, "kind": "complaint", "score": 0.766, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 품질 / 상태: RESOLVED / 상품: 휴대용 충전기 / 내용: 충전기가 사용 중 뜨거워지고 완충까지 너무 오래 걸립니다. 안전한지 확인 부탁드립니다. / 처리결과: 발열 기준 초과 여부 확인을 위해 회수 검사 진행. 불량 판정되어 전액 환불 처리. 동일 로트 제품 품질 점검 요청.", "category": "품질", "order_id": 107, "seller_id": 1, "product_id": 6, "customer_id": 3, "has_resolution": true, "source_created_at": "2026-09-18 16:49:04"}, {"id": 108, "kind": "complaint", "score": 0.765, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 환불 / 상태: RESOLVED / 상품: 무선 이어폰 / 내용: 이어폰 한쪽 소리가 작아서 환불 요청했는데 환불 금액이 아직 입금되지 않았습니다. / 처리결과: 카드사 환불 처리 기간 3~5영업일 안내 및 카드 취소 승인번호 전달. 이후 입금 확인.", "category": "환불", "order_id": 115, "seller_id": 1, "product_id": 1, "customer_id": 5, "has_resolution": true, "source_created_at": "2026-08-05 16:49:04"}]}', 'local', '2026-09-29 17:05:41'),
	(7, 1, 'ADMIN', 'INSIGHT', NULL, NULL, '최근 90일', '### 운영 리포트  \n\n---\n\n#### **1) 핵심 이슈 Top 3 (영향 범위·근거)**  \n1. **품질 문제 (영향 범위: 5건)**  \n   - **근거**: 불만 105(휴대용 충전기, RESOLVED), 불만 2(휴대용 충전기, OPEN), 불만 107(블루투스 스피커, RESOLVED), 후기 113(폼롤러), 후기 115(휴대용 충전기).  \n   - **요약**: 충전 속도 저하, 발열, 연결 불안정, 표면 딱딱 등 품질 관련 불만 및 후기 증가.  \n\n2. **배송 및 포장 문제 (영향 범위: 3건)**  \n   - **근거**: 불만 104(밀폐 유리 용기 세트, RESOLVED), 불만 111(데스크 조명, RESOLVED), 후기 111(밀폐 유리 용기 세트).  \n   - **요약**: 파손, 포장 부족, 박스 찌그러짐 등 배송 및 포장 관련 불만 발생.  \n\n3. **교환/환불 처리 지연 (영향 범위: 2건)**  \n   - **근거**: 불만 108(무선 이어폰, RESOLVED), 불만 105(휴대용 충전기, RESOLVED).  \n   - **요약**: 환불 처리 지연, 교환 요청 시 제한적 처리.  \n\n---\n\n#### **2) 상품별 위험 신호**  \n- **휴대용 충전기**:  \n  - **위험 신호**: 불만 105, 불만 2, 후기 115, 후기 2(공통: 충전 속도 저하, 발열, 헐거운 케이블).  \n  - **요약**: 품질 불안정, 반복적 불만 발생.  \n- **밀폐 유리 용기 세트**:  \n  - **위험 신호**: 불만 104, 후기 111(공통: 포장 부족, 파손).  \n  - **요약**: 배송 중 파손, 포장 개선 필요.  \n- **블루투스 스피커**:  \n  - **위험 신호**: 불만 107, 후기 106(공통: 연결 불안정, 저음 약함).  \n  - **요약**: 기술적 결함, 고객 불만 증가.  \n- **폼롤러**:  \n  - **위험 신호**: 후기 113(표면 딱딱, 통증 유발).  \n  - **요약**: 사용자 경험 저하, 제품 디자인 개선 필요.  \n\n---\n\n#### **3) 이번 주 즉시 조치**  \n1. **품질 불만 대응**:  \n   - **불만 2(휴대용 충전기, OPEN)**: 품질 점검 및 교환/환불 옵션 제공.  \n   - **불만 107(블루투스 스피커, RESOLVED)**: 펌웨어 업데이트 안내 재확인.  \n2. **포장 개선**:  \n   - **밀폐 유리 용기 세트**: 2중 완충재 적용, 포장 점검 요청.  \n3. **환불 처리 가이드라인 강화**:  \n   - **불만 108(무선 이어폰, RESOLVED)**: 환불 처리 기간 명시 및 카드 취소 승인번호 공유.  \n\n---\n\n#### **4) 정책·매뉴얼·상세페이지 개선 제안**  \n- **정책 개선**:  \n  - **품질 보증 기준**: 충전 속도, 발열, 연결 안정성 등 기준 명시.  \n  - **환불 처리 기간**: 3~5영업일 이내 처리 필수.  \n- **매뉴얼 개선**:  \n  - **교환/환불 절차**: 사전 안내 및 처리 기간 명시.  \n  - **포장 안내**: 2중 완충재 사용, 제품 보호 조치 기준 추가.  \n- **상세페이지 개선**:  \n  - **제품 설명**: 표면 소재, 충전 속도, 연결 안정성 등 추가.  \n  - **고객 후기**: 부정적 후기 별도 분류 및 개선 사항 표시.  \n\n---\n\n#### **5) 추적할 지표**  \n1. **불만 처리 시간**: OPEN → RESOLVED 기간.  \n2. **고객 만족도**: 환불/교환 처리 후 리뷰 평점 변화.  \n3. **반복 불만율**: 동일 상품/카테고리 반복 불만 발생 비율.  \n4. **포장 관련 불만 비율**: 배송파손/포장 부족 관련 불만 비중.  \n5. **제품 리뷰 평점**: 품질 관련 상품의 평점 변화 추적.  \n\n---  \n**참고**: 모든 수치는 제공된 통계 기준이며, 근거 ID는 각 항목에 명시됨.', '{"stats": {"reviews": [{"id": 6, "name": "휴대용 충전기", "reviews": 3, "negative": "3", "avg_rating": "1.67"}, {"id": 9, "name": "밀폐 유리 용기 세트", "reviews": 1, "negative": "1", "avg_rating": "2.00"}, {"id": 2, "name": "블루투스 스피커", "reviews": 1, "negative": "0", "avg_rating": "3.00"}, {"id": 10, "name": "폼롤러", "reviews": 2, "negative": "0", "avg_rating": "4.00"}, {"id": 5, "name": "요가 매트", "reviews": 1, "negative": "0", "avg_rating": "4.00"}, {"id": 8, "name": "스마트 워치", "reviews": 1, "negative": "0", "avg_rating": "4.00"}, {"id": 1, "name": "무선 이어폰", "reviews": 2, "negative": "0", "avg_rating": "4.50"}, {"id": 3, "name": "보온 텀블러", "reviews": 2, "negative": "0", "avg_rating": "4.50"}, {"id": 4, "name": "데스크 조명", "reviews": 2, "negative": "0", "avg_rating": "5.00"}, {"id": 7, "name": "노이즈캔슬링 헤드폰", "reviews": 1, "negative": "0", "avg_rating": "5.00"}], "complaints": [{"n": 3, "status": "OPEN", "category": "배송"}, {"n": 3, "status": "RESOLVED", "category": "품질"}, {"n": 1, "status": "OPEN", "category": "품질"}, {"n": 1, "status": "IN_PROGRESS", "category": "교환"}, {"n": 1, "status": "RESOLVED", "category": "배송파손"}, {"n": 1, "status": "IN_PROGRESS", "category": "품질"}, {"n": 1, "status": "RESOLVED", "category": "환불"}, {"n": 1, "status": "RESOLVED", "category": "배송"}, {"n": 1, "status": "OPEN", "category": "교환"}, {"n": 1, "status": "RESOLVED", "category": "문의"}]}, "sources": [{"id": 113, "kind": "review", "score": 0.821, "rating": 3, "excerpt": "[상품후기] 상품: 폼롤러(운동용품) / 평점: 3점 / 내용: 표면이 딱딱해서 초보자에게는 통증이 있습니다. 부드러운 버전이 있으면 좋겠어요.", "category": "운동용품", "seller_id": 3, "product_id": 10, "customer_id": 5, "source_created_at": "2026-09-03 16:49:04"}, {"id": 106, "kind": "review", "score": 0.809, "rating": 3, "excerpt": "[상품후기] 상품: 블루투스 스피커(전자기기) / 평점: 3점 / 내용: 음량은 충분하지만 저음이 약하고 블루투스 연결이 가끔 끊깁니다.", "category": "전자기기", "seller_id": 1, "product_id": 2, "customer_id": 3, "source_created_at": "2026-09-12 16:49:04"}, {"id": 115, "kind": "review", "score": 0.802, "rating": 2, "excerpt": "[상품후기] 상품: 휴대용 충전기(전자기기) / 평점: 2점 / 내용: 케이블 단자가 헐거워 충전이 자주 끊깁니다. 충전 속도도 광고보다 느립니다.", "category": "전자기기", "seller_id": 1, "product_id": 6, "customer_id": 2, "source_created_at": "2026-09-15 16:49:04"}, {"id": 105, "kind": "complaint", "score": 0.816, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 품질 / 상태: RESOLVED / 상품: 휴대용 충전기 / 내용: 충전기가 사용 중 뜨거워지고 완충까지 너무 오래 걸립니다. 안전한지 확인 부탁드립니다. / 처리결과: 발열 기준 초과 여부 확인을 위해 회수 검사 진행. 불량 판정되어 전액 환불 처리. 동일 로트 제품 품질 점검 요청.", "category": "품질", "order_id": 107, "seller_id": 1, "product_id": 6, "customer_id": 3, "has_resolution": true, "source_created_at": "2026-09-18 16:49:04"}, {"id": 2, "kind": "complaint", "score": 0.815, "status": "OPEN", "excerpt": "[고객불만] 분류: 품질 / 상태: OPEN / 상품: 휴대용 충전기 / 내용: 휴대용 충전기 충전 속도가 안내보다 느립니다.", "category": "품질", "order_id": 2, "seller_id": 1, "product_id": 6, "customer_id": 1, "has_resolution": false, "source_created_at": "2026-09-29 13:26:15"}, {"id": 107, "kind": "complaint", "score": 0.808, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 품질 / 상태: RESOLVED / 상품: 블루투스 스피커 / 내용: 블루투스 스피커 연결이 자주 끊깁니다. / 처리결과: 펌웨어 최신 버전 업데이트 방법 안내 후 증상 해소. 해소되지 않으면 교환 가능함을 안내.", "category": "품질", "order_id": 106, "seller_id": 1, "product_id": 2, "customer_id": 3, "has_resolution": true, "source_created_at": "2026-09-13 16:49:04"}, {"id": 111, "kind": "review", "score": 0.82, "rating": 2, "excerpt": "[상품후기] 상품: 밀폐 유리 용기 세트(생활용품) / 평점: 2점 / 내용: 배송 중 유리 용기 하나가 깨져서 왔습니다. 포장 완충재가 부족했습니다.", "category": "생활용품", "seller_id": 2, "product_id": 9, "customer_id": 4, "source_created_at": "2026-09-25 16:49:04"}, {"id": 104, "kind": "complaint", "score": 0.802, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 배송파손 / 상태: RESOLVED / 상품: 밀폐 유리 용기 세트 / 내용: 유리 용기 세트 중 1개가 깨진 상태로 도착했습니다. 사진 첨부 가능합니다. / 처리결과: 파손 사진 확인 후 동일 상품 1개 무상 재발송. 택배사 파손 접수 및 포장 완충재 2중 적용 기준으로 변경.", "category": "배송파손", "order_id": 109, "seller_id": 2, "product_id": 9, "customer_id": 4, "has_resolution": true, "source_created_at": "2026-09-25 16:49:04"}, {"id": 2, "kind": "review", "score": 0.776, "rating": 2, "excerpt": "[상품후기] 상품: 휴대용 충전기(전자기기) / 평점: 2점 / 내용: 충전 속도가 느려서 이 충전기는 다시 구매하고 싶지 않습니다.", "category": "전자기기", "seller_id": 1, "product_id": 6, "customer_id": 1, "source_created_at": "2026-09-24 13:26:15"}, {"id": 108, "kind": "complaint", "score": 0.805, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 환불 / 상태: RESOLVED / 상품: 무선 이어폰 / 내용: 이어폰 한쪽 소리가 작아서 환불 요청했는데 환불 금액이 아직 입금되지 않았습니다. / 처리결과: 카드사 환불 처리 기간 3~5영업일 안내 및 카드 취소 승인번호 전달. 이후 입금 확인.", "category": "환불", "order_id": 115, "seller_id": 1, "product_id": 1, "customer_id": 5, "has_resolution": true, "source_created_at": "2026-08-05 16:49:04"}, {"id": 111, "kind": "complaint", "score": 0.791, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 배송 / 상태: RESOLVED / 상품: 데스크 조명 / 내용: 데스크 조명 박스가 찌그러져 도착했습니다. 제품은 정상 작동합니다. / 처리결과: 제품 정상 작동 확인. 사과와 함께 적립금 2,000원 지급. 판매자에게 포장 개선 요청 전달.", "category": "배송", "order_id": 113, "seller_id": 2, "product_id": 4, "customer_id": 1, "has_resolution": true, "source_created_at": "2026-08-12 16:49:04"}]}', 'local', '2026-09-29 17:06:53'),
	(8, 1, 'ADMIN', 'RAG_ASK', NULL, NULL, '환불 지연 불만의 과거 처리 방식은?', '질문에 대한 답변은 다음과 같습니다:  \n\n**과거 처리 방식:**  \n1. **품질 문제로 인한 환불 지연:**  \n   - [불만 105] 휴대용 충전기의 발열 및 충전 속도 문제로, 회수 검사 및 불량 판정을 위해 시간이 소요되었고, 전액 환불 처리에 일정 기간이 소요되었습니다.  \n   - [불만 2] 충전 속도가 느리다는 품질 불만은 처리 상태가 \'OPEN\'으로, 추가 조치 기준이 명확하지 않아 처리 지연 가능성이 있었습니다.  \n\n2. **환불 처리 기간 지연:**  \n   - [불만 108] 무선 이어폰 환불 요청 시, 카드사 환불 처리 기간(3~5영업일)이 사전 안내되었으나, 입금까지 시간이 소요되어 고객 불편이 발생했습니다.  \n\n3. **재발송으로 인한 간접적 환불 지연:**  \n   - [불만 104] 파손 상품의 무상 재발송 처리 시, 택배사 파손 접수 및 포장 개선 절차가 추가로 소요되어 환불 절차에 영향을 미쳤을 수 있습니다.  \n\n**운영 개선안:**  \n1. **품질 검사 효율화:**  \n   - [불만 105]와 [불만 2]의 사례에서 품질 검사 시간을 단축하기 위해, 외부 전문 검사 기관과 협업하거나 AI 기반 자동 검사를 도입할 수 있습니다.  \n\n2. **환불 처리 기간 명확화:**  \n   - [불만 108]의 사례처럼, 환불 처리 기간을 사전에 고객에게 명확히 안내하고, 카드사와의 협업을 통해 즉시 환불 가능 여부를 확인하는 시스템을 구축해야 합니다.  \n\n3. **재발송 절차 최적화:**  \n   - [불만 104]의 경우, 파손 상품 재발송 시 포장 개선 절차를 사전에 적용하여 재발송 시간을 단축하고, 환불과 병행 처리를 고려할 수 있습니다.  \n\n**참고:**  \n- [후기 2], [후기 115] 등은 개인적인 사용 경험을 반영한 후기로, 환불 지연과 직접적인 연관성이 없습니다.  \n- 근거가 부족한 부분은 확인 필요로 표시했습니다.', '{"sources": [{"id": 115, "kind": "review", "score": 0.812, "rating": 2, "excerpt": "[상품후기] 상품: 휴대용 충전기(전자기기) / 평점: 2점 / 내용: 케이블 단자가 헐거워 충전이 자주 끊깁니다. 충전 속도도 광고보다 느립니다.", "category": "전자기기", "seller_id": 1, "product_id": 6, "customer_id": 2, "source_created_at": "2026-09-15 16:49:04"}, {"id": 106, "kind": "review", "score": 0.801, "rating": 3, "excerpt": "[상품후기] 상품: 블루투스 스피커(전자기기) / 평점: 3점 / 내용: 음량은 충분하지만 저음이 약하고 블루투스 연결이 가끔 끊깁니다.", "category": "전자기기", "seller_id": 1, "product_id": 2, "customer_id": 3, "source_created_at": "2026-09-12 16:49:04"}, {"id": 2, "kind": "review", "score": 0.79, "rating": 2, "excerpt": "[상품후기] 상품: 휴대용 충전기(전자기기) / 평점: 2점 / 내용: 충전 속도가 느려서 이 충전기는 다시 구매하고 싶지 않습니다.", "category": "전자기기", "seller_id": 1, "product_id": 6, "customer_id": 1, "source_created_at": "2026-09-24 13:26:15"}, {"id": 110, "kind": "review", "score": 0.787, "rating": 4, "excerpt": "[상품후기] 상품: 보온 텀블러(생활용품) / 평점: 4점 / 내용: 보온은 6시간 정도 유지됩니다. 뚜껑 패킹 세척이 조금 번거롭습니다.", "category": "생활용품", "seller_id": 2, "product_id": 3, "customer_id": 4, "source_created_at": "2026-09-25 16:49:04"}, {"id": 113, "kind": "review", "score": 0.783, "rating": 3, "excerpt": "[상품후기] 상품: 폼롤러(운동용품) / 평점: 3점 / 내용: 표면이 딱딱해서 초보자에게는 통증이 있습니다. 부드러운 버전이 있으면 좋겠어요.", "category": "운동용품", "seller_id": 3, "product_id": 10, "customer_id": 5, "source_created_at": "2026-09-03 16:49:04"}, {"id": 114, "kind": "review", "score": 0.783, "rating": 4, "excerpt": "[상품후기] 상품: 스마트 워치(전자기기) / 평점: 4점 / 내용: 심박 측정이 정확하고 디자인이 좋습니다. 배터리는 이틀 정도 갑니다.", "category": "전자기기", "seller_id": 1, "product_id": 8, "customer_id": 5, "source_created_at": "2026-09-27 16:49:04"}, {"id": 105, "kind": "complaint", "score": 0.822, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 품질 / 상태: RESOLVED / 상품: 휴대용 충전기 / 내용: 충전기가 사용 중 뜨거워지고 완충까지 너무 오래 걸립니다. 안전한지 확인 부탁드립니다. / 처리결과: 발열 기준 초과 여부 확인을 위해 회수 검사 진행. 불량 판정되어 전액 환불 처리. 동일 로트 제품 품질 점검 요청.", "category": "품질", "order_id": 107, "seller_id": 1, "product_id": 6, "customer_id": 3, "has_resolution": true, "source_created_at": "2026-09-18 16:49:04"}, {"id": 108, "kind": "complaint", "score": 0.817, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 환불 / 상태: RESOLVED / 상품: 무선 이어폰 / 내용: 이어폰 한쪽 소리가 작아서 환불 요청했는데 환불 금액이 아직 입금되지 않았습니다. / 처리결과: 카드사 환불 처리 기간 3~5영업일 안내 및 카드 취소 승인번호 전달. 이후 입금 확인.", "category": "환불", "order_id": 115, "seller_id": 1, "product_id": 1, "customer_id": 5, "has_resolution": true, "source_created_at": "2026-08-05 16:49:04"}, {"id": 104, "kind": "complaint", "score": 0.802, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 배송파손 / 상태: RESOLVED / 상품: 밀폐 유리 용기 세트 / 내용: 유리 용기 세트 중 1개가 깨진 상태로 도착했습니다. 사진 첨부 가능합니다. / 처리결과: 파손 사진 확인 후 동일 상품 1개 무상 재발송. 택배사 파손 접수 및 포장 완충재 2중 적용 기준으로 변경.", "category": "배송파손", "order_id": 109, "seller_id": 2, "product_id": 9, "customer_id": 4, "has_resolution": true, "source_created_at": "2026-09-25 16:49:04"}, {"id": 2, "kind": "complaint", "score": 0.797, "status": "OPEN", "excerpt": "[고객불만] 분류: 품질 / 상태: OPEN / 상품: 휴대용 충전기 / 내용: 휴대용 충전기 충전 속도가 안내보다 느립니다.", "category": "품질", "order_id": 2, "seller_id": 1, "product_id": 6, "customer_id": 1, "has_resolution": false, "source_created_at": "2026-09-29 13:26:15"}, {"id": 107, "kind": "complaint", "score": 0.792, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 품질 / 상태: RESOLVED / 상품: 블루투스 스피커 / 내용: 블루투스 스피커 연결이 자주 끊깁니다. / 처리결과: 펌웨어 최신 버전 업데이트 방법 안내 후 증상 해소. 해소되지 않으면 교환 가능함을 안내.", "category": "품질", "order_id": 106, "seller_id": 1, "product_id": 2, "customer_id": 3, "has_resolution": true, "source_created_at": "2026-09-13 16:49:04"}]}', 'local', '2026-09-29 17:22:33'),
	(9, 1, 'ADMIN', 'RAG_ASK', NULL, NULL, '배송 미수령 불만에 어떻게 대응해야 돼', '**처리 기준**  \n1. **배송 중 파손/손상 사례**  \n   - [불만 104] 배송 중 파손 시, 파손 사진 확인 후 동일 상품 무상 재발송 및 택배사 파손 접수 절차 진행. 포장 완충재 기준 강화.  \n   - [불만 111] 포장 외관 손상 시, 제품 정상 작동 확인 후 사과 및 적립금 지급, 판매자에게 포장 개선 요청 전달.  \n\n2. **배송 완료 후 수령 미사례**  \n   - [불만 1] 배송 완료로 표시되나 수령 실패 시, 택배사와 협의해 재발송 또는 환불 조치.  \n   - 처리 시, 고객에게 배송 추적 번호 제공 및 택배사 연락처 안내.  \n\n**운영 개선안**  \n1. **배송 추적 시스템 강화**  \n   - 택배사와 실시간 연동해 배송 상태를 고객에게 알림.  \n   - 배송 완료 후 24시간 이내에 수령 여부 확인 절차 도입.  \n\n2. **포장 개선 및 품질 검사**  \n   - [불만 104] 기준으로 포장 완충재 2중 적용 의무화.  \n   - 고가 상품 및 유리/유리 용기 등 취약 품목에 대해 별도 포장 검토 절차 도입.  \n\n3. **고객 소통 강화**  \n   - 배송 지연/파손 발생 시, 고객에게 사전 안내 및 보상 옵션(재발송/환불) 제공.  \n   - [불만 108]처럼 환불 지연 시, 카드사 처리 기간 명확히 안내 및 진행 상황 공유.  \n\n**근거 부족 사항**  \n- [불만 1]은 처리 중이므로, 택배사와의 협업 방안이 추가 필요.  \n- [후기 111]은 포장 관련 불만이지만, 수령 미사례와 직접 연관되지 않음.', '{"sources": [{"id": 113, "kind": "review", "score": 0.785, "rating": 3, "excerpt": "[상품후기] 상품: 폼롤러(운동용품) / 평점: 3점 / 내용: 표면이 딱딱해서 초보자에게는 통증이 있습니다. 부드러운 버전이 있으면 좋겠어요.", "category": "운동용품", "seller_id": 3, "product_id": 10, "customer_id": 5, "source_created_at": "2026-09-03 16:49:04"}, {"id": 106, "kind": "review", "score": 0.782, "rating": 3, "excerpt": "[상품후기] 상품: 블루투스 스피커(전자기기) / 평점: 3점 / 내용: 음량은 충분하지만 저음이 약하고 블루투스 연결이 가끔 끊깁니다.", "category": "전자기기", "seller_id": 1, "product_id": 2, "customer_id": 3, "source_created_at": "2026-09-12 16:49:04"}, {"id": 105, "kind": "review", "score": 0.775, "rating": 5, "excerpt": "[상품후기] 상품: 데스크 조명(생활용품) / 평점: 5점 / 내용: 밝기 단계가 세밀하고 눈부심이 적어 야간 작업용으로 좋습니다.", "category": "생활용품", "seller_id": 2, "product_id": 4, "customer_id": 2, "source_created_at": "2026-08-24 16:49:04"}, {"id": 111, "kind": "review", "score": 0.774, "rating": 2, "excerpt": "[상품후기] 상품: 밀폐 유리 용기 세트(생활용품) / 평점: 2점 / 내용: 배송 중 유리 용기 하나가 깨져서 왔습니다. 포장 완충재가 부족했습니다.", "category": "생활용품", "seller_id": 2, "product_id": 9, "customer_id": 4, "source_created_at": "2026-09-25 16:49:04"}, {"id": 112, "kind": "review", "score": 0.772, "rating": 4, "excerpt": "[상품후기] 상품: 요가 매트(운동용품) / 평점: 4점 / 내용: 미끄럼 방지는 좋은데 처음에 고무 냄새가 강했습니다. 며칠 환기하니 괜찮아요.", "category": "운동용품", "seller_id": 3, "product_id": 5, "customer_id": 5, "source_created_at": "2026-09-03 16:49:04"}, {"id": 104, "kind": "review", "score": 0.771, "rating": 4, "excerpt": "[상품후기] 상품: 무선 이어폰(전자기기) / 평점: 4점 / 내용: 통화 품질이 깔끔하고 가볍습니다. 다만 충전 케이스 힌지가 약간 헐거워요.", "category": "전자기기", "seller_id": 1, "product_id": 1, "customer_id": 2, "source_created_at": "2026-08-25 16:49:04"}, {"id": 104, "kind": "complaint", "score": 0.775, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 배송파손 / 상태: RESOLVED / 상품: 밀폐 유리 용기 세트 / 내용: 유리 용기 세트 중 1개가 깨진 상태로 도착했습니다. 사진 첨부 가능합니다. / 처리결과: 파손 사진 확인 후 동일 상품 1개 무상 재발송. 택배사 파손 접수 및 포장 완충재 2중 적용 기준으로 변경.", "category": "배송파손", "order_id": 109, "seller_id": 2, "product_id": 9, "customer_id": 4, "has_resolution": true, "source_created_at": "2026-09-25 16:49:04"}, {"id": 111, "kind": "complaint", "score": 0.771, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 배송 / 상태: RESOLVED / 상품: 데스크 조명 / 내용: 데스크 조명 박스가 찌그러져 도착했습니다. 제품은 정상 작동합니다. / 처리결과: 제품 정상 작동 확인. 사과와 함께 적립금 2,000원 지급. 판매자에게 포장 개선 요청 전달.", "category": "배송", "order_id": 113, "seller_id": 2, "product_id": 4, "customer_id": 1, "has_resolution": true, "source_created_at": "2026-08-12 16:49:04"}, {"id": 105, "kind": "complaint", "score": 0.767, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 품질 / 상태: RESOLVED / 상품: 휴대용 충전기 / 내용: 충전기가 사용 중 뜨거워지고 완충까지 너무 오래 걸립니다. 안전한지 확인 부탁드립니다. / 처리결과: 발열 기준 초과 여부 확인을 위해 회수 검사 진행. 불량 판정되어 전액 환불 처리. 동일 로트 제품 품질 점검 요청.", "category": "품질", "order_id": 107, "seller_id": 1, "product_id": 6, "customer_id": 3, "has_resolution": true, "source_created_at": "2026-09-18 16:49:04"}, {"id": 1, "kind": "complaint", "score": 0.766, "status": "OPEN", "excerpt": "[고객불만] 분류: 배송 / 상태: OPEN / 상품: 무선 이어폰 / 내용: 배송 완료로 표시되었으나 상품을 받지 못했습니다.", "category": "배송", "order_id": 1, "seller_id": 1, "product_id": 1, "customer_id": 1, "has_resolution": false, "source_created_at": "2026-09-29 13:26:15"}, {"id": 108, "kind": "complaint", "score": 0.761, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 환불 / 상태: RESOLVED / 상품: 무선 이어폰 / 내용: 이어폰 한쪽 소리가 작아서 환불 요청했는데 환불 금액이 아직 입금되지 않았습니다. / 처리결과: 카드사 환불 처리 기간 3~5영업일 안내 및 카드 취소 승인번호 전달. 이후 입금 확인.", "category": "환불", "order_id": 115, "seller_id": 1, "product_id": 1, "customer_id": 5, "has_resolution": true, "source_created_at": "2026-08-05 16:49:04"}]}', 'local', '2026-09-29 17:30:15'),
	(10, 1, 'ADMIN', 'RAG_ASK', NULL, NULL, '환불 지연 불만의 과거 처리 방식은?', '질문: 환불 지연 불만의 과거 처리 방식은?  \n**검색된 근거에 기반한 답변:**  \n[불만 108]에 따르면, 환불 지연 사례에서 고객은 환불 금액이 입금되지 않았다고 요청했습니다. 처리 결과로, 카드사 환불 처리 기간(3~5영업일)을 안내하고 카드 취소 승인번호를 전달한 후 입금 확인을 진행했습니다. 이는 환불 지연 시 **환불 처리 기간을 사전에 안내하고, 카드사 절차에 따른 입금 일정을 고객에게 명확히 전달**하는 방식으로 처리되었습니다.  \n\n**운영 개선안:**  \n1. **환불 처리 기간 표준화**: 카드사 및 은행별 처리 기간을 사전에 공유하여 고객 기대치 조절.  \n2. **실시간 환불 상태 추적 시스템**: 고객에게 환불 진행 상황을 실시간으로 알림(예: 이메일/앱 알림).  \n3. **환불 지연 시 보상 정책**: 지연 시 일정 금액의 보상 또는 할인 쿠폰 제공을 고려.  \n\n**참고:** [불만 108] 외 다른 사례는 환불 지연이 아닌 제품 결함이나 배송 문제로 인한 환불 처리 사례입니다.', '{"sources": [{"id": 115, "kind": "review", "score": 0.812, "rating": 2, "excerpt": "[상품후기] 상품: 휴대용 충전기(전자기기) / 평점: 2점 / 내용: 케이블 단자가 헐거워 충전이 자주 끊깁니다. 충전 속도도 광고보다 느립니다.", "category": "전자기기", "seller_id": 1, "product_id": 6, "customer_id": 2, "source_created_at": "2026-09-15 16:49:04"}, {"id": 106, "kind": "review", "score": 0.801, "rating": 3, "excerpt": "[상품후기] 상품: 블루투스 스피커(전자기기) / 평점: 3점 / 내용: 음량은 충분하지만 저음이 약하고 블루투스 연결이 가끔 끊깁니다.", "category": "전자기기", "seller_id": 1, "product_id": 2, "customer_id": 3, "source_created_at": "2026-09-12 16:49:04"}, {"id": 2, "kind": "review", "score": 0.79, "rating": 2, "excerpt": "[상품후기] 상품: 휴대용 충전기(전자기기) / 평점: 2점 / 내용: 충전 속도가 느려서 이 충전기는 다시 구매하고 싶지 않습니다.", "category": "전자기기", "seller_id": 1, "product_id": 6, "customer_id": 1, "source_created_at": "2026-09-24 13:26:15"}, {"id": 110, "kind": "review", "score": 0.787, "rating": 4, "excerpt": "[상품후기] 상품: 보온 텀블러(생활용품) / 평점: 4점 / 내용: 보온은 6시간 정도 유지됩니다. 뚜껑 패킹 세척이 조금 번거롭습니다.", "category": "생활용품", "seller_id": 2, "product_id": 3, "customer_id": 4, "source_created_at": "2026-09-25 16:49:04"}, {"id": 113, "kind": "review", "score": 0.783, "rating": 3, "excerpt": "[상품후기] 상품: 폼롤러(운동용품) / 평점: 3점 / 내용: 표면이 딱딱해서 초보자에게는 통증이 있습니다. 부드러운 버전이 있으면 좋겠어요.", "category": "운동용품", "seller_id": 3, "product_id": 10, "customer_id": 5, "source_created_at": "2026-09-03 16:49:04"}, {"id": 114, "kind": "review", "score": 0.783, "rating": 4, "excerpt": "[상품후기] 상품: 스마트 워치(전자기기) / 평점: 4점 / 내용: 심박 측정이 정확하고 디자인이 좋습니다. 배터리는 이틀 정도 갑니다.", "category": "전자기기", "seller_id": 1, "product_id": 8, "customer_id": 5, "source_created_at": "2026-09-27 16:49:04"}, {"id": 105, "kind": "complaint", "score": 0.822, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 품질 / 상태: RESOLVED / 상품: 휴대용 충전기 / 내용: 충전기가 사용 중 뜨거워지고 완충까지 너무 오래 걸립니다. 안전한지 확인 부탁드립니다. / 처리결과: 발열 기준 초과 여부 확인을 위해 회수 검사 진행. 불량 판정되어 전액 환불 처리. 동일 로트 제품 품질 점검 요청.", "category": "품질", "order_id": 107, "seller_id": 1, "product_id": 6, "customer_id": 3, "has_resolution": true, "source_created_at": "2026-09-18 16:49:04"}, {"id": 108, "kind": "complaint", "score": 0.817, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 환불 / 상태: RESOLVED / 상품: 무선 이어폰 / 내용: 이어폰 한쪽 소리가 작아서 환불 요청했는데 환불 금액이 아직 입금되지 않았습니다. / 처리결과: 카드사 환불 처리 기간 3~5영업일 안내 및 카드 취소 승인번호 전달. 이후 입금 확인.", "category": "환불", "order_id": 115, "seller_id": 1, "product_id": 1, "customer_id": 5, "has_resolution": true, "source_created_at": "2026-08-05 16:49:04"}, {"id": 104, "kind": "complaint", "score": 0.802, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 배송파손 / 상태: RESOLVED / 상품: 밀폐 유리 용기 세트 / 내용: 유리 용기 세트 중 1개가 깨진 상태로 도착했습니다. 사진 첨부 가능합니다. / 처리결과: 파손 사진 확인 후 동일 상품 1개 무상 재발송. 택배사 파손 접수 및 포장 완충재 2중 적용 기준으로 변경.", "category": "배송파손", "order_id": 109, "seller_id": 2, "product_id": 9, "customer_id": 4, "has_resolution": true, "source_created_at": "2026-09-25 16:49:04"}, {"id": 2, "kind": "complaint", "score": 0.797, "status": "OPEN", "excerpt": "[고객불만] 분류: 품질 / 상태: OPEN / 상품: 휴대용 충전기 / 내용: 휴대용 충전기 충전 속도가 안내보다 느립니다.", "category": "품질", "order_id": 2, "seller_id": 1, "product_id": 6, "customer_id": 1, "has_resolution": false, "source_created_at": "2026-09-29 13:26:15"}, {"id": 107, "kind": "complaint", "score": 0.792, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 품질 / 상태: RESOLVED / 상품: 블루투스 스피커 / 내용: 블루투스 스피커 연결이 자주 끊깁니다. / 처리결과: 펌웨어 최신 버전 업데이트 방법 안내 후 증상 해소. 해소되지 않으면 교환 가능함을 안내.", "category": "품질", "order_id": 106, "seller_id": 1, "product_id": 2, "customer_id": 3, "has_resolution": true, "source_created_at": "2026-09-13 16:49:04"}]}', 'local', '2026-09-29 17:35:10'),
	(11, 1, 'ADMIN', 'INSIGHT', NULL, NULL, '최근 7일', '### 운영 리포트  \n\n#### 1) 핵심 이슈 Top 3 (영향 범위·근거)  \n1. **배송 관련 이슈 (영향 범위: 3건)**  \n   - **근거**: 불만 1 (배송 미도착), 불만 2 (품질), 불만 112 (교환 요청).  \n   - **특징**: 배송 상태가 OPEN인 불만 1건과 교환 요청 1건이 포함됨.  \n\n2. **교환 요청 (영향 범위: 2건)**  \n   - **근거**: 불만 112 (스마트 워치 스트랩 사이즈 불일치), 교환 관련 불만 1건.  \n   - **특징**: 교환 요청이 2건 발생하며, 제품 맞춤성 문제로 추정됨.  \n\n3. **품질 문제 (영향 범위: 1건)**  \n   - **근거**: 불만 2 (휴대용 충전기 충전 속도 느림).  \n   - **특징**: 제품 성능 불만으로, 리뷰(후기 2)와 관련된 지속적 불만으로 예상됨.  \n\n---\n\n#### 2) 상품별 위험 신호  \n1. **밀폐 유리 용기 세트**  \n   - **위험 신호**:  \n     - 후기 111 (배송 중 파손), 불만 104 (배송파손)로 **배송 품질 문제** 발생.  \n     - 평점 2.00, 부정 후기 1건으로 **고객 신뢰 저하** 위험.  \n\n2. **휴대용 충전기**  \n   - **위험 신호**:  \n     - 후기 2 (충전 속도 느림), 불만 2 (품질 불만)로 **제품 성능 불만** 집중.  \n     - 평점 2.00, 부정 후기 1건으로 **판매 성과 악화** 가능성.  \n\n---\n\n#### 3) 이번 주 즉시 조치  \n1. **배송 관련 조치**  \n   - 불만 1 (배송 미도착): 택배사와 협업해 배송 상태 확인 및 재발송.  \n   - 불만 112 (교환 요청): 스트랩 사이즈 교환 절차 즉시 진행.  \n\n2. **품질 문제 대응**  \n   - 불만 2 (충전 속도 불만): 휴대용 충전기의 충전 속도 테스트 재검토 및 **성능 기준 명시화**.  \n\n3. **포장 개선**  \n   - 불만 104 (배송파손) 사례 반영해 **2중 완충재 적용**으로 파손 방지.  \n\n---\n\n#### 4) 정책·매뉴얼·상세페이지 개선 제안  \n1. **제품 설명 개선**  \n   - 휴대용 충전기: "충전 속도" 항목에 **실제 테스트 결과** 및 **기준치 명시**.  \n   - 밀폐 유리 용기 세트: "포장 방식" 설명에 **2중 완충재 적용** 명시.  \n\n2. **불만 처리 매뉴얼 업데이트**  \n   - 배송파손 사례: **사진 첨부 필수**로 변경, 처리 기준 공유.  \n   - 교환 요청: **제품 맞춤성 검토 절차** 명시.  \n\n3. **고객 안내 강화**  \n   - 상품 상세페이지에 **제품 사용법**, **포장 방식**, **환불/교환 조건** 명확히 표기.  \n\n---\n\n#### 5) 추적할 지표  \n1. **불만 처리 기간**: OPEN 상태 불만의 평균 처리 시간.  \n2. **평점 변화**: 후기 평점 개선 여부 (특히 2.00 평점 상품).  \n3. **교환/환불 비율**: 제품 맞춤성 문제로 인한 교환 요청 비율.  \n4. **배송 파손 발생률**: 포장 개선 후 배송 파손 사례 감소 여부.  \n5. **고객 만족도**: 리뷰 부정 반응 감소 및 긍정적 후기 증가.  \n\n---  \n**참고**: 모든 데이터는 제공된 통계 및 근거 ID 기준으로 작성됨.', '{"stats": {"reviews": [{"id": 6, "name": "휴대용 충전기", "reviews": 1, "negative": "1", "avg_rating": "2.00"}, {"id": 9, "name": "밀폐 유리 용기 세트", "reviews": 1, "negative": "1", "avg_rating": "2.00"}, {"id": 8, "name": "스마트 워치", "reviews": 1, "negative": "0", "avg_rating": "4.00"}, {"id": 3, "name": "보온 텀블러", "reviews": 2, "negative": "0", "avg_rating": "4.50"}], "complaints": [{"n": 3, "status": "OPEN", "category": "배송"}, {"n": 1, "status": "OPEN", "category": "품질"}, {"n": 1, "status": "IN_PROGRESS", "category": "교환"}, {"n": 1, "status": "RESOLVED", "category": "배송파손"}, {"n": 1, "status": "OPEN", "category": "교환"}]}, "sources": [{"id": 111, "kind": "review", "score": 0.801, "rating": 2, "excerpt": "[상품후기] 상품: 밀폐 유리 용기 세트(생활용품) / 평점: 2점 / 내용: 배송 중 유리 용기 하나가 깨져서 왔습니다. 포장 완충재가 부족했습니다.", "category": "생활용품", "seller_id": 2, "product_id": 9, "customer_id": 4, "source_created_at": "2026-09-25 16:49:04"}, {"id": 2, "kind": "review", "score": 0.789, "rating": 2, "excerpt": "[상품후기] 상품: 휴대용 충전기(전자기기) / 평점: 2점 / 내용: 충전 속도가 느려서 이 충전기는 다시 구매하고 싶지 않습니다.", "category": "전자기기", "seller_id": 1, "product_id": 6, "customer_id": 1, "source_created_at": "2026-09-24 13:26:15"}, {"id": 2, "kind": "complaint", "score": 0.815, "status": "OPEN", "excerpt": "[고객불만] 분류: 품질 / 상태: OPEN / 상품: 휴대용 충전기 / 내용: 휴대용 충전기 충전 속도가 안내보다 느립니다.", "category": "품질", "order_id": 2, "seller_id": 1, "product_id": 6, "customer_id": 1, "has_resolution": false, "source_created_at": "2026-09-29 13:26:15"}, {"id": 104, "kind": "complaint", "score": 0.797, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 배송파손 / 상태: RESOLVED / 상품: 밀폐 유리 용기 세트 / 내용: 유리 용기 세트 중 1개가 깨진 상태로 도착했습니다. 사진 첨부 가능합니다. / 처리결과: 파손 사진 확인 후 동일 상품 1개 무상 재발송. 택배사 파손 접수 및 포장 완충재 2중 적용 기준으로 변경.", "category": "배송파손", "order_id": 109, "seller_id": 2, "product_id": 9, "customer_id": 4, "has_resolution": true, "source_created_at": "2026-09-25 16:49:04"}, {"id": 1, "kind": "complaint", "score": 0.787, "status": "OPEN", "excerpt": "[고객불만] 분류: 배송 / 상태: OPEN / 상품: 무선 이어폰 / 내용: 배송 완료로 표시되었으나 상품을 받지 못했습니다.", "category": "배송", "order_id": 1, "seller_id": 1, "product_id": 1, "customer_id": 1, "has_resolution": false, "source_created_at": "2026-09-29 13:26:15"}, {"id": 112, "kind": "complaint", "score": 0.783, "status": "OPEN", "excerpt": "[고객불만] 분류: 교환 / 상태: OPEN / 상품: 스마트 워치 / 내용: 스마트 워치 스트랩 사이즈가 맞지 않아 교환하고 싶습니다.", "category": "교환", "order_id": 111, "seller_id": 1, "product_id": 8, "customer_id": 5, "has_resolution": false, "source_created_at": "2026-09-28 16:49:04"}]}', 'local', '2026-09-29 18:00:28'),
	(12, 2, 'SELLER', 'RAG_ASK', NULL, NULL, '파손 배송 불만을 줄이려면 포장을 어떻게 바꿔야 할까?', '제공된 근거에는 파손 배송을 방지하기 위한 구체적인 포장 변경 방안이 명시되지 않았습니다. [문서 1·2]에서는 파손 상품의 처리 절차와 환불 규정, 후기 작성 가이드라인 등을 다루고 있으나, 포장 개선에 대한 직접적인 조언은 없습니다. 또한 [불만 105]에서는 충전기의 발열 문제로 인한 회수 검사가 이루어졌지만, 이는 제품 설계나 품질 문제와 관련된 사례입니다. 따라서 현재 제공된 근거로는 포장 변경을 통한 파손 배송 감소 방안을 구체적으로 제시할 수 없습니다. 확인 필요.', '{"sources": [{"id": 2, "kind": "document", "score": 0.833, "title": "쇼핑몰_운영정책_고객안내_RAG용_초안.pdf", "excerpt": "된 판매 조건과 적용 법령에 따라 개별 안내한다. 고객에게 불리한 임의 기준을 AI 답변만으로 적용하지 않는다. 파손·하자와 안전 우려 파손된 유리 제품이나 발열 등 안전 우려가 있는 전자제품은 사용을 중지하고 고객센터에 즉시 문의하도록 안내한다. 운영자는 사진과 제품 정보를 확인하고 필요 시 판매자에게 안전 검토를 요청한다. 조사 전 정상 사용을 권고하지 않는다. 환불 진행 접수 → 사실 확인 → 처리 방법 안내 → 회수 또는 증빙 확인 → 환불 처리의 순서로 진행한다. 승인 여부와 환불 처리 일자는 신청 건별로 기록하고 고객에게", "document_id": 2}, {"id": 1, "kind": "document", "score": 0.833, "title": "쇼핑몰_운영정책_고객안내_RAG용_초안.pdf", "excerpt": "된 판매 조건과 적용 법령에 따라 개별 안내한다. 고객에게 불리한 임의 기준을 AI 답변만으로 적용하지 않는다. 파손·하자와 안전 우려 파손된 유리 제품이나 발열 등 안전 우려가 있는 전자제품은 사용을 중지하고 고객센터에 즉시 문의하도록 안내한다. 운영자는 사진과 제품 정보를 확인하고 필요 시 판매자에게 안전 검토를 요청한다. 조사 전 정상 사용을 권고하지 않는다. 환불 진행 접수 → 사실 확인 → 처리 방법 안내 → 회수 또는 증빙 확인 → 환불 처리의 순서로 진행한다. 승인 여부와 환불 처리 일자는 신청 건별로 기록하고 고객에게", "document_id": 1}, {"id": 1, "kind": "document", "score": 0.79, "title": "쇼핑몰_운영정책_고객안내_RAG용_초안.pdf", "excerpt": "인한다. 결제 완료 후 주문 변경 또는 취소를 원하면 출고 전 고객센터로 요청한다. 출고 여부와 결제 수단에 따른 처리 가능 범위를 확인하여 안내한다. 배송 배송 방법, 배송비, 지역별 추가 비용 및 예상 출고일은 결제 화면에 표시된 확정 안내를 따른다. 배송 지연이 예상되면 변경된 예상 일정과 고객의 선택 가능한 조치를 알린다. 배송 완료 표시 후 미수령 수령 장소와 배송 알림을 먼저 확인한 뒤, 주문번호와 운송장번호를 고객센터로 전달한다. 운영자는 배송 기록과 필요한 경우 배송 사진을 확인하고 배송업체에 조사 요청을 접수한다. ", "document_id": 1}, {"id": 2, "kind": "document", "score": 0.79, "title": "쇼핑몰_운영정책_고객안내_RAG용_초안.pdf", "excerpt": "인한다. 결제 완료 후 주문 변경 또는 취소를 원하면 출고 전 고객센터로 요청한다. 출고 여부와 결제 수단에 따른 처리 가능 범위를 확인하여 안내한다. 배송 배송 방법, 배송비, 지역별 추가 비용 및 예상 출고일은 결제 화면에 표시된 확정 안내를 따른다. 배송 지연이 예상되면 변경된 예상 일정과 고객의 선택 가능한 조치를 알린다. 배송 완료 표시 후 미수령 수령 장소와 배송 알림을 먼저 확인한 뒤, 주문번호와 운송장번호를 고객센터로 전달한다. 운영자는 배송 기록과 필요한 경우 배송 사진을 확인하고 배송업체에 조사 요청을 접수한다. ", "document_id": 2}, {"id": 106, "kind": "review", "score": 0.833, "rating": 3, "excerpt": "[상품후기] 상품: 블루투스 스피커(전자기기) / 평점: 3점 / 내용: 음량은 충분하지만 저음이 약하고 블루투스 연결이 가끔 끊깁니다.", "category": "전자기기", "seller_id": 1, "product_id": 2, "source_created_at": "2026-09-12 16:49:04"}, {"id": 104, "kind": "review", "score": 0.799, "rating": 4, "excerpt": "[상품후기] 상품: 무선 이어폰(전자기기) / 평점: 4점 / 내용: 통화 품질이 깔끔하고 가볍습니다. 다만 충전 케이스 힌지가 약간 헐거워요.", "category": "전자기기", "seller_id": 1, "product_id": 1, "source_created_at": "2026-08-25 16:49:04"}, {"id": 114, "kind": "review", "score": 0.785, "rating": 4, "excerpt": "[상품후기] 상품: 스마트 워치(전자기기) / 평점: 4점 / 내용: 심박 측정이 정확하고 디자인이 좋습니다. 배터리는 이틀 정도 갑니다.", "category": "전자기기", "seller_id": 1, "product_id": 8, "source_created_at": "2026-09-27 16:49:04"}, {"id": 115, "kind": "review", "score": 0.779, "rating": 2, "excerpt": "[상품후기] 상품: 휴대용 충전기(전자기기) / 평점: 2점 / 내용: 케이블 단자가 헐거워 충전이 자주 끊깁니다. 충전 속도도 광고보다 느립니다.", "category": "전자기기", "seller_id": 1, "product_id": 6, "source_created_at": "2026-09-15 16:49:04"}, {"id": 2, "kind": "review", "score": 0.776, "rating": 2, "excerpt": "[상품후기] 상품: 휴대용 충전기(전자기기) / 평점: 2점 / 내용: 충전 속도가 느려서 이 충전기는 다시 구매하고 싶지 않습니다.", "category": "전자기기", "seller_id": 1, "product_id": 6, "source_created_at": "2026-09-24 13:26:15"}, {"id": 107, "kind": "review", "score": 0.772, "rating": 1, "excerpt": "[상품후기] 상품: 휴대용 충전기(전자기기) / 평점: 1점 / 내용: 완충까지 5시간 이상 걸리고 사용 중 뜨거워집니다. 발열이 걱정됩니다.", "category": "전자기기", "seller_id": 1, "product_id": 6, "source_created_at": "2026-09-17 16:49:04"}, {"id": 107, "kind": "complaint", "score": 0.81, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 품질 / 상태: RESOLVED / 상품: 블루투스 스피커 / 내용: 블루투스 스피커 연결이 자주 끊깁니다. / 처리결과: 펌웨어 최신 버전 업데이트 방법 안내 후 증상 해소. 해소되지 않으면 교환 가능함을 안내.", "category": "품질", "order_id": 106, "seller_id": 1, "product_id": 2, "has_resolution": true, "source_created_at": "2026-09-13 16:49:04"}, {"id": 105, "kind": "complaint", "score": 0.81, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 품질 / 상태: RESOLVED / 상품: 휴대용 충전기 / 내용: 충전기가 사용 중 뜨거워지고 완충까지 너무 오래 걸립니다. 안전한지 확인 부탁드립니다. / 처리결과: 발열 기준 초과 여부 확인을 위해 회수 검사 진행. 불량 판정되어 전액 환불 처리. 동일 로트 제품 품질 점검 요청.", "category": "품질", "order_id": 107, "seller_id": 1, "product_id": 6, "has_resolution": true, "source_created_at": "2026-09-18 16:49:04"}, {"id": 2, "kind": "complaint", "score": 0.781, "status": "OPEN", "excerpt": "[고객불만] 분류: 품질 / 상태: OPEN / 상품: 휴대용 충전기 / 내용: 휴대용 충전기 충전 속도가 안내보다 느립니다.", "category": "품질", "order_id": 2, "seller_id": 1, "product_id": 6, "has_resolution": false, "source_created_at": "2026-09-29 13:26:15"}, {"id": 1, "kind": "complaint", "score": 0.78, "status": "OPEN", "excerpt": "[고객불만] 분류: 배송 / 상태: OPEN / 상품: 무선 이어폰 / 내용: 배송 완료로 표시되었으나 상품을 받지 못했습니다.", "category": "배송", "order_id": 1, "seller_id": 1, "product_id": 1, "has_resolution": false, "source_created_at": "2026-09-29 13:26:15"}, {"id": 108, "kind": "complaint", "score": 0.778, "status": "RESOLVED", "excerpt": "[고객불만] 분류: 환불 / 상태: RESOLVED / 상품: 무선 이어폰 / 내용: 이어폰 한쪽 소리가 작아서 환불 요청했는데 환불 금액이 아직 입금되지 않았습니다. / 처리결과: 카드사 환불 처리 기간 3~5영업일 안내 및 카드 취소 승인번호 전달. 이후 입금 확인.", "category": "환불", "order_id": 115, "seller_id": 1, "product_id": 1, "has_resolution": true, "source_created_at": "2026-08-05 16:49:04"}]}', 'local', '2026-09-29 18:09:24'),
	(13, 2, 'SELLER', 'INSIGHT', NULL, NULL, '최근 30일', '**운영 리포트**  \n\n---\n\n### 1) 핵심 이슈 Top 3 (영향 범위·근거)  \n- **품질 문제 (영향 범위: 4건, 근거 ID: 불만 2, 불만 105, 후기 115, 후기 2)**  \n  - 휴대용 충전기 관련 불만 2건(OPEN, RESOLVED) 및 후기 2건(2점)이 충전 속도 느림, 케이블 단자 불안정, 발열 문제를 제기.  \n  - 불만 105(RESOLVED)는 전동 제품 발열 기준 초과로 전액 환불 처리됨.  \n\n- **블루투스 스피커 연결 불안정 (영향 범위: 2건, 근거 ID: 불만 107, 후기 106)**  \n  - 불만 107(RESOLVED) 및 후기 106은 블루투스 연결 끊김 문제로 펌웨어 업데이트 권장 및 교환 가능성을 안내.  \n\n- **교환 요청 (영향 범위: 1건, 근거 ID: 불만 112)**  \n  - 스마트 워치 스트랩 사이즈 불일치로 교환 요청.  \n\n---\n\n### 2) 상품별 위험 신호  \n- **휴대용 충전기**  \n  - **위험 신호**: 충전 속도 느림, 발열, 케이블 단자 불안정(후기 115, 2, 불만 2, 105).  \n  - **영향**: 평점 1.67(최저), 불만 2건, 1건 해결됨.  \n\n- **블루투스 스피커**  \n  - **위험 신호**: 블루투스 연결 끊김(후기 106, 불만 107).  \n  - **영향**: 평점 3점, 불만 1건 해결됨.  \n\n- **스마트 워치**  \n  - **위험 신호**: 스트랩 사이즈 불일치(불만 112).  \n  - **영향**: 교환 요청 1건.  \n\n---\n\n### 3) 이번 주 즉시 조치  \n- **휴대용 충전기 품질 개선**  \n  - **조치**: 불만 2(OPEN) 및 후기 115, 2에 대해 충전 속도 저하 원인 분석. 케이블 단자 강화 및 충전 속도 테스트 반복.  \n  - **근거**: 불만 2, 후기 115, 2.  \n\n- **블루투스 스피커 연결 안정화**  \n  - **조치**: 불만 107에 대한 펌웨어 업데이트 안내 재전달. 연결 불안정 시 교환 가능성을 명시.  \n  - **근거**: 불만 107.  \n\n- **스마트 워치 스트랩 사이즈 확인**  \n  - **조치**: 불만 112에 대해 스트랩 사이즈 재검토. 교환 시 유연한 정책 적용.  \n  - **근거**: 불만 112.  \n\n---\n\n### 4) 정책·매뉴얼·상세페이지 개선 제안  \n- **충전기 상세페이지 개선**  \n  - **제안**: 충전 속도, 케이블 단자 강도, 발열 안전 기준 명시. "실제 속도는 기기 사양에 따라 다를 수 있음" 경고 문구 추가.  \n  - **근거**: 불만 2, 105, 후기 115, 2.  \n\n- **블루투스 스피커 매뉴얼 개선**  \n  - **제안**: 블루투스 연결 안정화를 위한 펌웨어 업데이트 절차 명시. 연결 끊김 시 교환 절차 안내.  \n  - **근거**: 불만 107, 후기 106.  \n\n- **스마트 워치 상세페이지 개선**  \n  - **제안**: 스트랩 사이즈 옵션 확대 및 교환 가능 여부 명시.  \n  - **근거**: 불만 112.  \n\n---\n\n### 5) 추적할 지표  \n- **해결률**: OPEN 상태 불만/후기 처리 완료 비율 (불만 2, 불만 112).  \n- **평점 변화**: 휴대용 충전기 평점 개선 여부 (1.67 → 3점 이상).  \n- **교환 요청률**: 스마트 워치 교환 요청 감소 여부.  \n- **불만 재발률**: 품질 관련 불만 재발 여부 (불만 105, 2).  \n\n---  \n**참고**: 모든 데이터는 제공된 통계 및 근거 ID 기반으로 작성됨.', '{"stats": {"reviews": [{"id": 6, "name": "휴대용 충전기", "reviews": 3, "negative": "3", "avg_ra