-- 테이블 mysqlragdb0.answer_logs 구조 내보내기
DROP TABLE IF EXISTS `answer_logs`;
CREATE TABLE IF NOT EXISTS `answer_logs` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `customer_id` bigint DEFAULT NULL,
  `question` text NOT NULL,
  `answer` longtext NOT NULL,
  `source_json` json DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `customer_id` (`customer_id`),
  CONSTRAINT `answer_logs_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb3;

-- 테이블 데이터 mysqlragdb0.answer_logs:~1 rows (대략적) 내보내기
DELETE FROM `answer_logs`;
INSERT INTO `answer_logs` (`id`, `customer_id`, `question`, `answer`, `source_json`, `created_at`) VALUES
	(1, 1, '환불 받는 방법 알려줘', '제공된 불만 데이터와 매뉴얼 정보는 환불 방법에 대한 구체적인 설명을 포함하지 않습니다. 불만 데이터는 배송 지연, 품질 문제 등에 대한 내용만 포함하고 있으며, 환불 절차에 대한 근거가 부족합니다. 환불 방법을 확인하려면 해당 플랫폼의 공식 고객센터나 이용약관을 참고해야 합니다.', '[]', '2026-09-29 16:34:09');

-- 테이블 mysqlragdb0.app_users 구조 내보내기
DROP TABLE IF EXISTS `app_users`;
CREATE TABLE IF NOT EXISTS `app_users` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `username` varchar(50) NOT NULL,
  `display_name` varchar(100) NOT NULL,
  `role` enum('ADMIN','SELLER','BUYER') NOT NULL,
  `customer_id` bigint DEFAULT NULL,
  `seller_id` bigint DEFAULT NULL,
  `active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`),
  KEY `customer_id` (`customer_id`),
  KEY `seller_id` (`seller_id`),
  CONSTRAINT `app_users_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`),
  CONSTRAINT `app_users_ibfk_2` FOREIGN KEY (`seller_id`) REFERENCES `sellers` (`id`),
  CONSTRAINT `app_users_chk_1` CHECK (((`role` = _utf8mb4'ADMIN') or ((`role` = _utf8mb4'SELLER') and (`seller_id` is not null)) or ((`role` = _utf8mb4'BUYER') and (`customer_id` is not null))))
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb3;

