-- 테이블 mysqlragdb0.complaint_replies 구조 내보내기
DROP TABLE IF EXISTS `complaint_replies`;
CREATE TABLE IF NOT EXISTS `complaint_replies` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `complaint_id` bigint NOT NULL,
  `manual_document_id` bigint DEFAULT NULL,
  `author_user_id` bigint DEFAULT NULL,
  `content` text NOT NULL,
  `status` enum('DRAFT','APPROVED','SENT') NOT NULL DEFAULT 'DRAFT',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `complaint_id` (`complaint_id`),
  KEY `manual_document_id` (`manual_document_id`),
  KEY `fk_complaint_replies_author` (`author_user_id`),
  CONSTRAINT `complaint_replies_ibfk_1` FOREIGN KEY (`complaint_id`) REFERENCES `complaints` (`id`),
  CONSTRAINT `complaint_replies_ibfk_2` FOREIGN KEY (`manual_document_id`) REFERENCES `source_documents` (`id`),
  CONSTRAINT `fk_complaint_replies_author` FOREIGN KEY (`author_user_id`) REFERENCES `app_users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb3;

