-- 테이블 mysqlragdb0.document_chunks 구조 내보내기
DROP TABLE IF EXISTS `document_chunks`;
CREATE TABLE IF NOT EXISTS `document_chunks` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `document_id` bigint NOT NULL,
  `chunk_no` int NOT NULL,
  `content` text NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `document_id` (`document_id`,`chunk_no`),
  CONSTRAINT `document_chunks_ibfk_1` FOREIGN KEY (`document_id`) REFERENCES `source_documents` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb3;

-- 테이블 데이터 mysqlragdb0.document_chunks:~12 rows (대략적) 내보내기
DELETE FROM `document_chunks`;
INSERT INTO `document_chunks` (`id`, `document_id`, `chunk_no`, `content`) VALUES
	(1, 1, 0, '쇼핑몰 운영 정책 · 고객 안내 | 승인 전 초안 1 쇼핑몰 운영 정책 · 고객 안내 문서 상태: 운영 전 검토용 초안 | 작성 기준: 첨부한 front_mysqlrag_0lhy(1).zip / back_mysqlrag_0lhy(1).zip | 작성일: 2026-09-29 이 문서는 쇼핑몰의 고객 안내와 RAG 상담용 원문으로 사용할 수 있도록 작성한 예시 정책이다. 실제 상호, 연락처, 배송비, 반품 주소, 처리 기한 및 법정 고지 사항은 운영 담당자가 확정해야 한다. 대괄호 항목을 채우고 승인한 뒤 고객에게 공개한다. 01. 이용 범위와 담당자 서비스 범위 상품 조회, 주문, 구매 후기 작성, 고객 문의·불만 접수, AI 기반 상담 및 상품 추천을 제공한다. 상품별 판매자는 상품 설명과 판매 관련 문의를 관리하며, 쇼핑몰 운영자는 전체 운영과 분쟁 조정을 담당한다. 고객센터 안내 고객센터: [전화번호 / 이메일 / 운영 시간] | 판매자 정보: 각 상품 상세 화면에서 확인 | 반품 수령 주소: [주소]. 고객 문의 시 주문번호와 상품명을 함께 알려주면 확인에 도움이 된다. 02. 주문·결제·배송 안내 주문과 결제 주문 내용과 결제 상태는 주문 내역에서 확인한다. 결제 완료 후 주문 변경 또는 취소를 원하면 출고 전 고객센터로 요청한다. 출고 여부와 결제 수단에 따른 처리 가능 범위를 확인하여 안내한다. 배송 배송 방법, 배송비, '),
	(2, 1, 1, '인한다. 결제 완료 후 주문 변경 또는 취소를 원하면 출고 전 고객센터로 요청한다. 출고 여부와 결제 수단에 따른 처리 가능 범위를 확인하여 안내한다. 배송 배송 방법, 배송비, 지역별 추가 비용 및 예상 출고일은 결제 화면에 표시된 확정 안내를 따른다. 배송 지연이 예상되면 변경된 예상 일정과 고객의 선택 가능한 조치를 알린다. 배송 완료 표시 후 미수령 수령 장소와 배송 알림을 먼저 확인한 뒤, 주문번호와 운송장번호를 고객센터로 전달한다. 운영자는 배송 기록과 필요한 경우 배송 사진을 확인하고 배송업체에 조사 요청을 접수한다. 조사 결과가 확정되기 전에는 분실 책임이나 환불 여부를 단정하지 않는다. 03. 교환·반품·환불 신청 방법 주문번호, 상품명, 신청 사유와 상품 상태를 고객센터에 알린다. 파손·하자라면 포장 및 상품 사진을 함께 제공하면 확인에 도움이 된다. 접수 후 운영자가 판매자와 주문·배송·결제 내역을 확인하여 절차를 안내한다. 판단 기준 쇼핑몰 운영 정책 · 고객 안내 | 승인 전 초안 2 단순 변심, 표시 내용과 다른 상품, 파손·하자, 오배송은 사유를 구분해 처리한다. 신청 가능 기간, 왕복 배송비 부담, 제외 사유 및 환급 시점은 확정된 판매 조건과 적용 법령에 따라 개별 안내한다. 고객에게 불리한 임의 기준을 AI 답변만으로 적용하지 않는다. 파손·하자와 안전 우려 파손된 유리 제품이나 발열 등 안전 우려가 '),
	(3, 1, 2, '된 판매 조건과 적용 법령에 따라 개별 안내한다. 고객에게 불리한 임의 기준을 AI 답변만으로 적용하지 않는다. 파손·하자와 안전 우려 파손된 유리 제품이나 발열 등 안전 우려가 있는 전자제품은 사용을 중지하고 고객센터에 즉시 문의하도록 안내한다. 운영자는 사진과 제품 정보를 확인하고 필요 시 판매자에게 안전 검토를 요청한다. 조사 전 정상 사용을 권고하지 않는다. 환불 진행 접수 → 사실 확인 → 처리 방법 안내 → 회수 또는 증빙 확인 → 환불 처리의 순서로 진행한다. 승인 여부와 환불 처리 일자는 신청 건별로 기록하고 고객에게 알린다. 04. 후기·상품 추천 후기 작성 구매 내역과 배송 상태를 확인한 고객이 상품 후기를 작성한다. 평점과 후기에는 실제 사용 경험을 기재하며 개인정보나 타인의 권리를 침해하는 내용은 게시 전 검토할 수 있다. 판매자 답글 판매자는 본인 상품의 후기만 확인하여 답글 초안을 작성한다. AI가 만든 답글은 사실관계와 표현을 검토한 뒤 게시한다. 공개 답글에는 주문번호, 연락처, 주소와 다른 고객의 정보를 포함하지 않는다. 맞춤 추천 최근 3개월 구매 내역, 고객 본인의 후기와 유사한 상품 후기를 근거로 추천할 수 있다. 추천은 취향을 추정한 안내이며 상품 품질이나 적합성을 보증하지 않는다. 낮은 평점과 불만은 추천 검토 시 함께 반영한다. 05. 고객 불만 접수와 처리 접수 배송, 파손, 상품 품질, 결'),
	(4, 1, 3, '취향을 추정한 안내이며 상품 품질이나 적합성을 보증하지 않는다. 낮은 평점과 불만은 추천 검토 시 함께 반영한다. 05. 고객 불만 접수와 처리 접수 배송, 파손, 상품 품질, 결제, 환불 등으로 구분하여 불만 내용을 접수한다. 고객에게 접수 번호와 다음 확인 단계를 안내한다. 담당자 확인 운영자는 주문·배송·결제 이력과 같은 상품의 후기, 과거 유사 불만 및 관련 정책 문서를 함께 살펴본다. 판매자에게 전달하는 경우 해당 상품과 관련된 정보만 제공한다. 처리 결과 기록 확인 내용과 고객에게 안내한 조치를 불만 처리 결과에 기록한다. 해결 완료 상태로 변경할 때 처리 결과를 남겨 이후 유사 사례 검토에 활용한다. 처리 불가 또는 추가 조사 중이라면 사유와 다음 안내 시점을 기록한다. 06. AI 상담 및 문서 이용 상담 근거 쇼핑몰 운영 정책 · 고객 안내 | 승인 전 초안 3 AI는 등록된 정책 문서, 구매 후기, 불만·처리 사례를 검색하여 답변 초안을 생성한다. 확인 가능한 근거가 없거나 자료가 충돌하면 단정하지 않고 담당자 확인을 안내한다. 모델 선택 로컬 Ollama 또는 Gemini API로 답변을 생성할 수 있다. 문서 검색용 임베딩은 로컬 Ollama에서 만든다. 외부 모델 사용 시 전송 정보의 범위와 개인정보 처리 기준을 운영자가 사전에 확인해야 한다. 최종 승인 AI 초안은 관리자 또는 권한이 있는 판매자가 사실관계와'),
	(5, 1, 4, 'ama에서 만든다. 외부 모델 사용 시 전송 정보의 범위와 개인정보 처리 기준을 운영자가 사전에 확인해야 한다. 최종 승인 AI 초안은 관리자 또는 권한이 있는 판매자가 사실관계와 최신 정책을 검토한 후 승인·발송한다. AI 응답만으로 반품 거절, 환불 확정, 법적 판단 또는 고객에게 보내는 최종 약속을 하지 않는다. 접근 범위 구매자는 본인 불만과 공개 가능한 상품 후기를, 판매자는 본인 상품 관련 정보만 조회한다. 관리자는 전체 운영 자료를 업무 목적에 맞게 열람한다. 다른 고객의 식별정보를 상담 답변에 노출하지 않는다. 07. 개인정보·문의 취급 원칙 주문 처리, 고객 응대 및 서비스 개선에 필요한 정보만 업무 목적에 따라 이용한다. 실제 수집 항목, 보관 기간, 제3자 제공, 외부 AI 이용, 권리 행사 방법은 별도의 개인정보 처리방침과 운영 계약을 확정하여 고지한다. 이의 신청 답변이나 처리 결과에 이의가 있으면 [고객센터 연락처]로 접수 번호와 사유를 전달한다. 담당자가 원자료와 처리 이력을 다시 확인해 회신한다. 운영 승인 전 확정할 항목 구분 확정할 내용 사업자·연락처 상호, 사업자정보, 고객센터, 판매자 연락 경로, 반품 주소 배송 배송 방법, 비용, 추가 배송비, 출고 기준과 지연 안내 시점 교환·환불 신청 기한, 배송비 부담, 예외 조건, 회수 절차, 환급 시점 개인정보·AI 처리방침, 보유 기간, 외부 Gemin'),
	(6, 1, 5, ', 비용, 추가 배송비, 출고 기준과 지연 안내 시점 교환·환불 신청 기한, 배송비 부담, 예외 조건, 회수 절차, 환급 시점 개인정보·AI 처리방침, 보유 기간, 외부 Gemini 사용 시 데이터 처리 및 고지 운영 승인 정책 책임자, 승인일, 적용일, 개정 이력 RAG 업로드 안내: 확정본을 PDF로 저장하여 관리자 화면의 문서 적재 기능에 업로드한다. 이후 RAG 색인 상태와 실제 질문·답변 근거를 확인한다. 정책 개정 시 이전 버전의 검색 노출 여부를 운영자가 점검한다.'),
	(7, 2, 0, '쇼핑몰 운영 정책 · 고객 안내 | 승인 전 초안 1 쇼핑몰 운영 정책 · 고객 안내 문서 상태: 운영 전 검토용 초안 | 작성 기준: 첨부한 front_mysqlrag_0lhy(1).zip / back_mysqlrag_0lhy(1).zip | 작성일: 2026-09-29 이 문서는 쇼핑몰의 고객 안내와 RAG 상담용 원문으로 사용할 수 있도록 작성한 예시 정책이다. 실제 상호, 연락처, 배송비, 반품 주소, 처리 기한 및 법정 고지 사항은 운영 담당자가 확정해야 한다. 대괄호 항목을 채우고 승인한 뒤 고객에게 공개한다. 01. 이용 범위와 담당자 서비스 범위 상품 조회, 주문, 구매 후기 작성, 고객 문의·불만 접수, AI 기반 상담 및 상품 추천을 제공한다. 상품별 판매자는 상품 설명과 판매 관련 문의를 관리하며, 쇼핑몰 운영자는 전체 운영과 분쟁 조정을 담당한다. 고객센터 안내 고객센터: [전화번호 / 이메일 / 운영 시간] | 판매자 정보: 각 상품 상세 화면에서 확인 | 반품 수령 주소: [주소]. 고객 문의 시 주문번호와 상품명을 함께 알려주면 확인에 도움이 된다. 02. 주문·결제·배송 안내 주문과 결제 주문 내용과 결제 상태는 주문 내역에서 확인한다. 결제 완료 후 주문 변경 또는 취소를 원하면 출고 전 고객센터로 요청한다. 출고 여부와 결제 수단에 따른 처리 가능 범위를 확인하여 안내한다. 배송 배송 방법, 배송비, '),
	(8, 2, 1, '인한다. 결제 완료 후 주문 변경 또는 취소를 원하면 출고 전 고객센터로 요청한다. 출고 여부와 결제 수단에 따른 처리 가능 범위를 확인하여 안내한다. 배송 배송 방법, 배송비, 지역별 추가 비용 및 예상 출고일은 결제 화면에 표시된 확정 안내를 따른다. 배송 지연이 예상되면 변경된 예상 일정과 고객의 선택 가능한 조치를 알린다. 배송 완료 표시 후 미수령 수령 장소와 배송 알림을 먼저 확인한 뒤, 주문번호와 운송장번호를 고객센터로 전달한다. 운영자는 배송 기록과 필요한 경우 배송 사진을 확인하고 배송업체에 조사 요청을 접수한다. 조사 결과가 확정되기 전에는 분실 책임이나 환불 여부를 단정하지 않는다. 03. 교환·반품·환불 신청 방법 주문번호, 상품명, 신청 사유와 상품 상태를 고객센터에 알린다. 파손·하자라면 포장 및 상품 사진을 함께 제공하면 확인에 도움이 된다. 접수 후 운영자가 판매자와 주문·배송·결제 내역을 확인하여 절차를 안내한다. 판단 기준 쇼핑몰 운영 정책 · 고객 안내 | 승인 전 초안 2 단순 변심, 표시 내용과 다른 상품, 파손·하자, 오배송은 사유를 구분해 처리한다. 신청 가능 기간, 왕복 배송비 부담, 제외 사유 및 환급 시점은 확정된 판매 조건과 적용 법령에 따라 개별 안내한다. 고객에게 불리한 임의 기준을 AI 답변만으로 적용하지 않는다. 파손·하자와 안전 우려 파손된 유리 제품이나 발열 등 안전 우려가 '),
	(9, 2, 2, '된 판매 조건과 적용 법령에 따라 개별 안내한다. 고객에게 불리한 임의 기준을 AI 답변만으로 적용하지 않는다. 파손·하자와 안전 우려 파손된 유리 제품이나 발열 등 안전 우려가 있는 전자제품은 사용을 중지하고 고객센터에 즉시 문의하도록 안내한다. 운영자는 사진과 제품 정보를 확인하고 필요 시 판매자에게 안전 검토를 요청한다. 조사 전 정상 사용을 권고하지 않는다. 환불 진행 접수 → 사실 확인 → 처리 방법 안내 → 회수 또는 증빙 확인 → 환불 처리의 순서로 진행한다. 승인 여부와 환불 처리 일자는 신청 건별로 기록하고 고객에게 알린다. 04. 후기·상품 추천 후기 작성 구매 내역과 배송 상태를 확인한 고객이 상품 후기를 작성한다. 평점과 후기에는 실제 사용 경험을 기재하며 개인정보나 타인의 권리를 침해하는 내용은 게시 전 검토할 수 있다. 판매자 답글 판매자는 본인 상품의 후기만 확인하여 답글 초안을 작성한다. AI가 만든 답글은 사실관계와 표현을 검토한 뒤 게시한다. 공개 답글에는 주문번호, 연락처, 주소와 다른 고객의 정보를 포함하지 않는다. 맞춤 추천 최근 3개월 구매 내역, 고객 본인의 후기와 유사한 상품 후기를 근거로 추천할 수 있다. 추천은 취향을 추정한 안내이며 상품 품질이나 적합성을 보증하지 않는다. 낮은 평점과 불만은 추천 검토 시 함께 반영한다. 05. 고객 불만 접수와 처리 접수 배송, 파손, 상품 품질, 결'),
	(10, 2, 3, '취향을 추정한 안내이며 상품 품질이나 적합성을 보증하지 않는다. 낮은 평점과 불만은 추천 검토 시 함께 반영한다. 05. 고객 불만 접수와 처리 접수 배송, 파손, 상품 품질, 결제, 환불 등으로 구분하여 불만 내용을 접수한다. 고객에게 접수 번호와 다음 확인 단계를 안내한다. 담당자 확인 운영자는 주문·배송·결제 이력과 같은 상품의 후기, 과거 유사 불만 및 관련 정책 문서를 함께 살펴본다. 판매자에게 전달하는 경우 해당 상품과 관련된 정보만 제공한다. 처리 결과 기록 확인 내용과 고객에게 안내한 조치를 불만 처리 결과에 기록한다. 해결 완료 상태로 변경할 때 처리 결과를 남겨 이후 유사 사례 검토에 활용한다. 처리 불가 또는 추가 조사 중이라면 사유와 다음 안내 시점을 기록한다. 06. AI 상담 및 문서 이용 상담 근거 쇼핑몰 운영 정책 · 고객 안내 | 승인 전 초안 3 AI는 등록된 정책 문서, 구매 후기, 불만·처리 사례를 검색하여 답변 초안을 생성한다. 확인 가능한 근거가 없거나 자료가 충돌하면 단정하지 않고 담당자 확인을 안내한다. 모델 선택 로컬 Ollama 또는 Gemini API로 답변을 생성할 수 있다. 문서 검색용 임베딩은 로컬 Ollama에서 만든다. 외부 모델 사용 시 전송 정보의 범위와 개인정보 처리 기준을 운영자가 사전에 확인해야 한다. 최종 승인 AI 초안은 관리자 또는 권한이 있는 판매자가 사실관계와'),
	(11, 2, 4, 'ama에서 만든다. 외부 모델 사용 시 전송 정보의 범위와 개인정보 처리 기준을 운영자가 사전에 확인해야 한다. 최종 승인 AI 초안은 관리자 또는 권한이 있는 판매자가 사실관계와 최신 정책을 검토한 후 승인·발송한다. AI 응답만으로 반품 거절, 환불 확정, 법적 판단 또는 고객에게 보내는 최종 약속을 하지 않는다. 접근 범위 구매자는 본인 불만과 공개 가능한 상품 후기를, 판매자는 본인 상품 관련 정보만 조회한다. 관리자는 전체 운영 자료를 업무 목적에 맞게 열람한다. 다른 고객의 식별정보를 상담 답변에 노출하지 않는다. 07. 개인정보·문의 취급 원칙 주문 처리, 고객 응대 및 서비스 개선에 필요한 정보만 업무 목적에 따라 이용한다. 실제 수집 항목, 보관 기간, 제3자 제공, 외부 AI 이용, 권리 행사 방법은 별도의 개인정보 처리방침과 운영 계약을 확정하여 고지한다. 이의 신청 답변이나 처리 결과에 이의가 있으면 [고객센터 연락처]로 접수 번호와 사유를 전달한다. 담당자가 원자료와 처리 이력을 다시 확인해 회신한다. 운영 승인 전 확정할 항목 구분 확정할 내용 사업자·연락처 상호, 사업자정보, 고객센터, 판매자 연락 경로, 반품 주소 배송 배송 방법, 비용, 추가 배송비, 출고 기준과 지연 안내 시점 교환·환불 신청 기한, 배송비 부담, 예외 조건, 회수 절차, 환급 시점 개인정보·AI 처리방침, 보유 기간, 외부 Gemin'),
	(12, 2, 5, ', 비용, 추가 배송비, 출고 기준과 지연 안내 시점 교환·환불 신청 기한, 배송비 부담, 예외 조건, 회수 절차, 환급 시점 개인정보·AI 처리방침, 보유 기간, 외부 Gemini 사용 시 데이터 처리 및 고지 운영 승인 정책 책임자, 승인일, 적용일, 개정 이력 RAG 업로드 안내: 확정본을 PDF로 저장하여 관리자 화면의 문서 적재 기능에 업로드한다. 이후 RAG 색인 상태와 실제 질문·답변 근거를 확인한다. 정책 개정 시 이전 버전의 검색 노출 여부를 운영자가 점검한다.');

