-- 테이블 mysqlragdb0.recommendation_logs 구조 내보내기
DROP TABLE IF EXISTS `recommendation_logs`;
CREATE TABLE IF NOT EXISTS `recommendation_logs` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `customer_id` bigint NOT NULL,
  `answer` longtext NOT NULL,
  `evidence_json` json NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `customer_id` (`customer_id`),
  CONSTRAINT `recommendation_logs_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb3;

-- 테이블 데이터 mysqlragdb0.recommendation_logs:~5 rows (대략적) 내보내기
DELETE FROM `recommendation_logs`;
INSERT INTO `recommendation_logs` (`id`, `customer_id`, `answer`, `evidence_json`, `created_at`) VALUES
	(1, 2, '선호 카테고리는 **생활용품**과 **전자기기**입니다. 추천 상품 ID는 다음과 같습니다:  \n\n1. **3 (보온 텀블러)**: 사용자 후기 [review_id: 110]에서 4점 평가로 보온 기능에 만족감을 표현하며, 뚜껑 세척 편의성에 대한 의견이 있어 구매 시 참고할 수 있습니다.  \n2. **4 (데스크 조명)**: 사용자 후기에서 5점 평가로 야간 작업용으로 적합하다는 긍정적 평가가 있으며, 빛 조절 기능에 대한 만족도가 높습니다.  \n3. **7 (노이즈캔슬링 헤드폰)**: peer_reviews [review_id: 109]에서 5점 평가로 노이즈 캔슬링 성능과 배터리 수명에 대한 높은 만족도가 기록되어 있습니다.  \n\n부정 후기 상품(예: product_id 6)은 추천하지 않았습니다.', '{"reviews": [{"rating": 5, "content": "텀블러 보온력이 좋아 만족합니다.", "category": "생활용품", "product_id": 3}, {"rating": 2, "content": "케이블 단자가 헐거워 충전이 자주 끊깁니다. 충전 속도도 광고보다 느립니다.", "category": "전자기기", "product_id": 6}, {"rating": 4, "content": "통화 품질이 깔끔하고 가볍습니다. 다만 충전 케이스 힌지가 약간 헐거워요.", "category": "전자기기", "product_id": 1}, {"rating": 5, "content": "밝기 단계가 세밀하고 눈부심이 적어 야간 작업용으로 좋습니다.", "category": "생활용품", "product_id": 4}], "purchases": [{"category": "생활용품", "quantity": "3", "purchases": 2}, {"category": "전자기기", "quantity": "2", "purchases": 2}], "peer_reviews": [{"rating": 4, "content": "[상품후기] 상품: 보온 텀블러(생활용품) / 평점: 4점 / 내용: 보온은 6시간 정도 유지됩니다. 뚜껑 패킹 세척이 조금 번거롭습니다.", "review_id": 110, "product_id": 3}, {"rating": 4, "content": "[상품후기] 상품: 요가 매트(운동용품) / 평점: 4점 / 내용: 미끄럼 방지는 좋은데 처음에 고무 냄새가 강했습니다. 며칠 환기하니 괜찮아요.", "review_id": 112, "product_id": 5}, {"rating": 4, "content": "[상품후기] 상품: 스마트 워치(전자기기) / 평점: 4점 / 내용: 심박 측정이 정확하고 디자인이 좋습니다. 배터리는 이틀 정도 갑니다.", "review_id": 114, "product_id": 8}, {"rating": 5, "content": "[상품후기] 상품: 노이즈캔슬링 헤드폰(전자기기) / 평점: 5점 / 내용: 노이즈캔슬링 성능이 뛰어나 지하철에서도 조용합니다. 배터리도 오래갑니다.", "review_id": 109, "product_id": 7}, {"rating": 5, "content": "[상품후기] 상품: 요가 매트(운동용품) / 평점: 5점 / 내용: 두께가 적당하고 무릎이 아프지 않습니다. 휴대용 스트랩이 유용해요.", "review_id": 117, "product_id": 5}]}', '2026-09-29 16:57:13'),
	(2, 2, '추천 상품 ID: 7, 8, 9  \n추천 이유:  \n1. **7 (노이즈캔슬링 헤드폰)**: [후기 ID 109]에서 노이즈캔슬링 성능이 뛰어나고 배터리 수명이 길다는 긍정적 후기 제공. 전자기기 카테고리에 속하며, 구매 이력에 해당 분야의 상품 구매가 있음.  \n2. **8 (스마트 워치)**: [후기 ID 114]에서 심박 측정 정확성과 디자인에 대한 긍정적 후기 제공. 전자기기 카테고리에 속하며, 구매 이력에 해당 분야의 상품 구매가 있음.  \n3. **9 (밀폐 유리 용기 세트)**: 생활용품 카테고리에 속하며, 사용자 구매 이력에 해당 분야의 상품 구매가 있음. 후기 없음에도 카테고리 기반으로 추천.  \n\n부정 후기 상품은 제외. 이미 구매한 상품(1, 4, 6, 3)은 우선하지 않음.', '{"reviews": [{"rating": 5, "content": "텀블러 보온력이 좋아 만족합니다.", "category": "생활용품", "product_id": 3}, {"rating": 2, "content": "케이블 단자가 헐거워 충전이 자주 끊깁니다. 충전 속도도 광고보다 느립니다.", "category": "전자기기", "product_id": 6}, {"rating": 4, "content": "통화 품질이 깔끔하고 가볍습니다. 다만 충전 케이스 힌지가 약간 헐거워요.", "category": "전자기기", "product_id": 1}, {"rating": 5, "content": "밝기 단계가 세밀하고 눈부심이 적어 야간 작업용으로 좋습니다.", "category": "생활용품", "product_id": 4}], "purchases": [{"category": "생활용품", "quantity": "3", "purchases": 2}, {"category": "전자기기", "quantity": "2", "purchases": 2}], "peer_reviews": [{"rating": 4, "content": "[상품후기] 상품: 보온 텀블러(생활용품) / 평점: 4점 / 내용: 보온은 6시간 정도 유지됩니다. 뚜껑 패킹 세척이 조금 번거롭습니다.", "review_id": 110, "product_id": 3}, {"rating": 4, "content": "[상품후기] 상품: 요가 매트(운동용품) / 평점: 4점 / 내용: 미끄럼 방지는 좋은데 처음에 고무 냄새가 강했습니다. 며칠 환기하니 괜찮아요.", "review_id": 112, "product_id": 5}, {"rating": 4, "content": "[상품후기] 상품: 스마트 워치(전자기기) / 평점: 4점 / 내용: 심박 측정이 정확하고 디자인이 좋습니다. 배터리는 이틀 정도 갑니다.", "review_id": 114, "product_id": 8}, {"rating": 5, "content": "[상품후기] 상품: 노이즈캔슬링 헤드폰(전자기기) / 평점: 5점 / 내용: 노이즈캔슬링 성능이 뛰어나 지하철에서도 조용합니다. 배터리도 오래갑니다.", "review_id": 109, "product_id": 7}, {"rating": 5, "content": "[상품후기] 상품: 요가 매트(운동용품) / 평점: 5점 / 내용: 두께가 적당하고 무릎이 아프지 않습니다. 휴대용 스트랩이 유용해요.", "review_id": 117, "product_id": 5}]}', '2026-09-29 16:59:11'),
	(3, 1, '선호 카테고리: 전자기기, 생활용품  \n추천 상품 ID:  \n1. **8 (스마트 워치)** - [후기 ID 114] 심박 측정이 정확하고 디자인이 좋습니다.  \n2. **3 (보온 텀블러)** - [후기 ID 110] 보온은 6시간 정도 유지됩니다.  \n3. **7 (노이즈캔슬링 헤드폰)** - 전자기기 카테고리에 해당하며, 가격이 129,000원으로 구매 이력과 유사한 범위입니다.', '{"reviews": [{"rating": 2, "content": "충전 속도가 느려서 이 충전기는 다시 구매하고 싶지 않습니다.", "category": "전자기기", "product_id": 6}, {"rating": 5, "content": "음질과 착용감이 좋아 전자기기를 선호합니다.", "category": "전자기기", "product_id": 1}, {"rating": 5, "content": "각도 조절이 자유롭고 USB 포트가 있어 편리합니다.", "category": "생활용품", "product_id": 4}], "purchases": [{"category": "전자기기", "quantity": "2", "purchases": 2}, {"category": "생활용품", "quantity": "1", "purchases": 1}], "peer_reviews": [{"rating": 4, "content": "[상품후기] 상품: 스마트 워치(전자기기) / 평점: 4점 / 내용: 심박 측정이 정확하고 디자인이 좋습니다. 배터리는 이틀 정도 갑니다.", "review_id": 114, "product_id": 8}, {"rating": 4, "content": "[상품후기] 상품: 요가 매트(운동용품) / 평점: 4점 / 내용: 미끄럼 방지는 좋은데 처음에 고무 냄새가 강했습니다. 며칠 환기하니 괜찮아요.", "review_id": 112, "product_id": 5}, {"rating": 4, "content": "[상품후기] 상품: 보온 텀블러(생활용품) / 평점: 4점 / 내용: 보온은 6시간 정도 유지됩니다. 뚜껑 패킹 세척이 조금 번거롭습니다.", "review_id": 110, "product_id": 3}, {"rating": 5, "content": "[상품후기] 상품: 요가 매트(운동용품) / 평점: 5점 / 내용: 두께가 적당하고 무릎이 아프지 않습니다. 휴대용 스트랩이 유용해요.", "review_id": 117, "product_id": 5}, {"rating": 4, "content": "[상품후기] 상품: 무선 이어폰(전자기기) / 평점: 4점 / 내용: 통화 품질이 깔끔하고 가볍습니다. 다만 충전 케이스 힌지가 약간 헐거워요.", "review_id": 104, "product_id": 1}]}', '2026-09-29 17:24:15'),
	(4, 2, '추천 상품 ID: 7, 8, 9  \n\n**추천 이유:**  \n- **7 (노이즈캔슬링 헤드폰)**: [후기 ID 109] 노이즈캔슬링 성능이 뛰어나 지하철에서도 조용하고, 배터리 수명도 길어 사용자 만족도 높음.  \n- **8 (스마트 워치)**: [후기 ID 114] 심박 측정 정확도와 디자인에 대한 긍정적 평가를 받으며, 배터리 수명도 이틀 분량으로 실용성 높음.  \n- **9 (밀폐 유리 용기 세트)**: 생활용품 카테고리에서 구매 이력이 있는 텀블러(제품 ID 3)와 동일한 카테고리로, 밀폐 용기 기능이 필요할 수 있음.  \n\n**주의:**  \n- **제품 ID 6**은 부정 후기([후기 ID 112] 케이블 단자 불량)로 추천하지 않음.  \n- **제품 ID 5**는 운동용품 카테고리로 선호 카테고리와 일치하지 않음.', '{"reviews": [{"rating": 5, "content": "텀블러 보온력이 좋아 만족합니다.", "category": "생활용품", "product_id": 3}, {"rating": 2, "content": "케이블 단자가 헐거워 충전이 자주 끊깁니다. 충전 속도도 광고보다 느립니다.", "category": "전자기기", "product_id": 6}, {"rating": 4, "content": "통화 품질이 깔끔하고 가볍습니다. 다만 충전 케이스 힌지가 약간 헐거워요.", "category": "전자기기", "product_id": 1}, {"rating": 5, "content": "밝기 단계가 세밀하고 눈부심이 적어 야간 작업용으로 좋습니다.", "category": "생활용품", "product_id": 4}], "purchases": [{"category": "생활용품", "quantity": "3", "purchases": 2}, {"category": "전자기기", "quantity": "2", "purchases": 2}], "peer_reviews": [{"rating": 4, "content": "[상품후기] 상품: 보온 텀블러(생활용품) / 평점: 4점 / 내용: 보온은 6시간 정도 유지됩니다. 뚜껑 패킹 세척이 조금 번거롭습니다.", "review_id": 110, "product_id": 3}, {"rating": 4, "content": "[상품후기] 상품: 요가 매트(운동용품) / 평점: 4점 / 내용: 미끄럼 방지는 좋은데 처음에 고무 냄새가 강했습니다. 며칠 환기하니 괜찮아요.", "review_id": 112, "product_id": 5}, {"rating": 4, "content": "[상품후기] 상품: 스마트 워치(전자기기) / 평점: 4점 / 내용: 심박 측정이 정확하고 디자인이 좋습니다. 배터리는 이틀 정도 갑니다.", "review_id": 114, "product_id": 8}, {"rating": 5, "content": "[상품후기] 상품: 노이즈캔슬링 헤드폰(전자기기) / 평점: 5점 / 내용: 노이즈캔슬링 성능이 뛰어나 지하철에서도 조용합니다. 배터리도 오래갑니다.", "review_id": 109, "product_id": 7}, {"rating": 5, "content": "[상품후기] 상품: 요가 매트(운동용품) / 평점: 5점 / 내용: 두께가 적당하고 무릎이 아프지 않습니다. 휴대용 스트랩이 유용해요.", "review_id": 117, "product_id": 5}]}', '2026-09-29 17:31:25'),
	(5, 1, '**추천 상품 ID:**  \n1. **7** (노이즈캔슬링 헤드폰) - 전자기기 카테고리에 속하며, 구매 이력에 전자기기 선호가 확인됨.  \n2. **3** (보온 텀블러) - [후기 ID 110]에서 "보온은 6시간 정도 유지됩니다"라는 긍정적 후기로, 생활용품 카테고리에 대한 선호가 있음.  \n3. **2** (블루투스 스피커) - 전자기기 카테고리에 속하며, 구매 이력에 전자기기 선호가 확인됨.  \n\n**추천 이유:**  \n- **7**은 전자기기 카테고리에 해당하며, 사용자가 전자기기를 선호하는 경향이 있음.  \n- **3**은 생활용품 카테고리에 속하며, [후기 ID 110]에서 "보온은 6시간 정도 유지됩니다"라는 긍정적 평가가 있음.  \n- **2**는 전자기기 카테고리에 속하며, 사용자가 전자기기를 선호하는 경향을 반영함.  \n- **6**과 **1**은 이미 구매한 상품이므로 제외.  \n- **5**는 운동용품 카테고리로 선호 카테고리와 일치하지 않음.', '{"reviews": [{"rating": 2, "content": "충전 속도가 느려서 이 충전기는 다시 구매하고 싶지 않습니다.", "category": "전자기기", "product_id": 6}, {"rating": 5, "content": "음질과 착용감이 좋아 전자기기를 선호합니다.", "category": "전자기기", "product_id": 1}, {"rating": 5, "content": "각도 조절이 자유롭고 USB 포트가 있어 편리합니다.", "category": "생활용품", "product_id": 4}], "purchases": [{"category": "전자기기", "quantity": "2", "purchases": 2}, {"category": "생활용품", "quantity": "1", "purchases": 1}], "peer_reviews": [{"rating": 4, "content": "[상품후기] 상품: 스마트 워치(전자기기) / 평점: 4점 / 내용: 심박 측정이 정확하고 디자인이 좋습니다. 배터리는 이틀 정도 갑니다.", "review_id": 114, "product_id": 8}, {"rating": 4, "content": "[상품후기] 상품: 요가 매트(운동용품) / 평점: 4점 / 내용: 미끄럼 방지는 좋은데 처음에 고무 냄새가 강했습니다. 며칠 환기하니 괜찮아요.", "review_id": 112, "product_id": 5}, {"rating": 4, "content": "[상품후기] 상품: 보온 텀블러(생활용품) / 평점: 4점 / 내용: 보온은 6시간 정도 유지됩니다. 뚜껑 패킹 세척이 조금 번거롭습니다.", "review_id": 110, "product_id": 3}, {"rating": 5, "content": "[상품후기] 상품: 요가 매트(운동용품) / 평점: 5점 / 내용: 두께가 적당하고 무릎이 아프지 않습니다. 휴대용 스트랩이 유용해요.", "review_id": 117, "product_id": 5}, {"rating": 4, "content": "[상품후기] 상품: 무선 이어폰(전자기기) / 평점: 4점 / 내용: 통화 품질이 깔끔하고 가볍습니다. 다만 충전 케이스 힌지가 약간 헐거워요.", "review_id": 104, "product_id": 1}]}', '2026-09-29 17:33:21'),
	(6, 1, '**선호 카테고리**: 전자기기, 생활용품  \n**추천 상품 ID**:  \n1. **8 (스마트 워치)** - [후기 ID 114] "심박 측정이 정확하고 디자인이 좋습니다. 배터리는 이틀 정도 갑니다."  \n2. **3 (보온 텀블러)** - [후기 ID 110] "보온은 6시간 정도 유지됩니다. 뚜껑 패킹 세척이 조금 번거롭습니다."  \n3. **2 (블루투스 스피커)** - 후기 없음 (단, 전자기기 카테고리에 해당하며, 구매 이력과 후기에서 선호하는 전자기기 제품과 유사한 특성을 가짐).  \n\n**추천 이유**:  \n- **8번 제품**은 전자기기 카테고리에서 구매자 후기 평점 4점으로 신뢰도가 높으며, 전자기기 구매 이력과 일치합니다.  \n- **3번 제품**은 생활용품 카테고리에서 후기 평점 4점으로 사용자 만족도가 높고, 생활용품 구매 이력과 일치합니다.  \n- **2번 제품**은 전자기기 카테고리에서 구매되지 않은 상품으로, 무선 이어폰(1번)과 유사한 전자기기 특성(Bluetooth 기능)을 가짐.  \n- **부정 후기 상품**은 제외하고, **이미 구매한 상품**(1, 4, 6)은 추천 대상에서 제외했습니다.', '{"reviews": [{"rating": 2, "content": "충전 속도가 느려서 이 충전기는 다시 구매하고 싶지 않습니다.", "category": "전자기기", "product_id": 6}, {"rating": 5, "content": "음질과 착용감이 좋아 전자기기를 선호합니다.", "category": "전자기기", "product_id": 1}, {"rating": 5, "content": "각도 조절이 자유롭고 USB 포트가 있어 편리합니다.", "category": "생활용품", "product_id": 4}], "purchases": [{"category": "전자기기", "quantity": "2", "purchases": 2}, {"category": "생활용품", "quantity": "1", "purchases": 1}], "peer_reviews": [{"rating": 4, "content": "[상품후기] 상품: 스마트 워치(전자기기) / 평점: 4점 / 내용: 심박 측정이 정확하고 디자인이 좋습니다. 배터리는 이틀 정도 갑니다.", "review_id": 114, "product_id": 8}, {"rating": 4, "content": "[상품후기] 상품: 요가 매트(운동용품) / 평점: 4점 / 내용: 미끄럼 방지는 좋은데 처음에 고무 냄새가 강했습니다. 며칠 환기하니 괜찮아요.", "review_id": 112, "product_id": 5}, {"rating": 4, "content": "[상품후기] 상품: 보온 텀블러(생활용품) / 평점: 4점 / 내용: 보온은 6시간 정도 유지됩니다. 뚜껑 패킹 세척이 조금 번거롭습니다.", "review_id": 110, "product_id": 3}, {"rating": 5, "content": "[상품후기] 상품: 요가 매트(운동용품) / 평점: 5점 / 내용: 두께가 적당하고 무릎이 아프지 않습니다. 휴대용 스트랩이 유용해요.", "review_id": 117, "product_id": 5}, {"rating": 4, "content": "[상품후기] 상품: 무선 이어폰(전자기기) / 평점: 4점 / 내용: 통화 품질이 깔끔하고 가볍습니다. 다만 충전 케이스 힌지가 약간 헐거워요.", "review_id": 104, "product_id": 1}]}', '2026-09-29 18:15:27');

-- 테이블 mysqlragdb0.review_replies 구조 내보내기
DROP TABLE IF EXISTS `review_replies`;
CREATE TABLE IF NOT EXISTS `review_replies` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `review_id` bigint NOT NULL,
  `seller_id` bigint DEFAULT NULL,
  `author_user_id` bigint NOT NULL,
  `content` text NOT NULL,
  `status` enum('DRAFT','PUBLISHED') NOT NULL DEFAULT 'DRAFT',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `seller_id` (`seller_id`),
  KEY `author_user_id` (`author_user_id`),
  KEY `idx_review_replies_review` (`review_id`,`created_at`),
  CONSTRAINT `review_replies_ibfk_1` FOREIGN KEY (`review_id`) REFERENCES `reviews` (`id`),
  CONSTRAINT `review_replies_ibfk_2` FOREIGN KEY (`seller_id`) REFERENCES `sellers` (`id`),
  CONSTRAINT `review_replies_ibfk_3` FOREIGN KEY (`author_user_id`) REFERENCES `app_users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb3;

