	(1, 107, 1, 2, '불편을 드려 죄송합니다. 발열 증상은 안전과 관련된 사항이라 고객센터를 통해 회수 검사를 진행하겠습니다.', 'PUBLISHED', '2026-09-29 16:49:04', '2026-09-29 16:49:04'),
	(2, 111, 2, 3, '파손된 상품으로 실망을 드려 죄송합니다. 포장 완충재를 보강했고 파손 상품은 재발송해 드렸습니다.', 'PUBLISHED', '2026-09-29 16:49:04', '2026-09-29 16:49:04');

-- 테이블 mysqlragdb0.reviews 구조 내보내기
DROP TABLE IF EXISTS `reviews`;
CREATE TABLE IF NOT EXISTS `reviews` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `customer_id` bigint NOT NULL,
  `product_id` bigint NOT NULL,
  `rating` tinyint NOT NULL,
  `content` text NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `customer_id` (`customer_id`),
  KEY `product_id` (`product_id`),
  CONSTRAINT `reviews_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`),
  CONSTRAINT `reviews_ibfk_2` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`),
  CONSTRAINT `reviews_chk_1` CHECK ((`rating` between 1 and 5))
) ENGINE=InnoDB AUTO_INCREMENT=118 DEFAULT CHARSET=utf8mb3;

